/* Données narratives : helpers + nœuds (S) + sommaire (STORIES) */
const H=x=>["h",x],N=x=>["n",x],Sy=x=>["s",x],K=()=>["x",""];
const S={
s0:{w:"carnet",m:[N("Gare de Lyon, 22h47. Hall 1, un jeudi de novembre."),N("Tu rentrais d'un dîner de collègues. Tu as fui avant le dessert, comme toujours."),N("Sur un banc, un carnet de cuir noir oublié. Pas de nom. À la dernière page, un numéro de téléphone et trois mots au stylo bleu : « Écris-moi quand même. »"),N("Le tableau des départs clique. Tu sors ton téléphone.")],
c:[["Bonsoir. J'ai trouvé un carnet à la gare de Lyon, avec ce numéro à la fin. Il est à vous ?","i1",{t:1}],["Hey ! Carnet de cuir trouvé gare de Lyon. Une récompense s'impose, non ? 😏","i1b",{t:-1}],["Je ne sais pas à qui il appartient, mais ce numéro a l'air important. Je peux le rendre ?","i1",{t:1}]]},
i1:{m:[H("..."),H("Ce numéro n'a pas reçu un seul message depuis quatorze mois.")],x:"i2"},
i1b:{m:[H("Une récompense."),H("Vous êtes le premier à écrire à ce numéro depuis quatorze mois, et vous commencez par une blague.")],x:"i2"},
i2:{m:[H("Qui êtes-vous ?")],c:[["Je m'appelle Sam. Je ne voulais pas vous déranger. Dites-moi où le déposer et j'y vais.","i3",{t:1}],["Je m'appelle Sam. Je rentrais chez moi et j'ai trouvé un carnet. Rien de plus mystérieux.","i3",{}]]},
i3:{m:[H("Ce numéro, c'était celui de ma sœur. Camille."),N("« C'était ». Tu relis le mot."),H("Je garde son téléphone allumé. Je le recharge tous les soirs, comme si elle pouvait encore appeler. Je sais que c'est absurde.")],c:[["Ce n'est pas absurde. On garde parfois une habitude parce que c'est tout ce qui reste.","i3a",{t:2}],["Je suis désolé. Je vais vous rendre le carnet et vous laisser tranquille.","i3b",{t:0}]]},
i3a:{m:[Sy("Tu écris au numéro de Camille. Celle qui répond est sa sœur, depuis le téléphone de Camille."),H("Merci. Je crois que j'avais besoin de l'entendre sans qu'on me dise de passer à autre chose."),H("Le carnet est à elle aussi. Je l'ai perdu vers 21h, j'ai couru tout le quai."),H("Vous l'avez ouvert ?")],c:[["Juste la dernière page, pour trouver à qui le rendre.","i4t",{t:1},"!"],["Non, jamais. Je l'ai à peine touché.","i4l",{l:1}]]},
i3b:{m:[H("Vous pouvez me le rendre sans vous occuper du reste. Je sais que c'est beaucoup à demander à un inconnu."),Sy("Tu sens que sa réponse est plus prudente, mais elle ne coupe pas la conversation."),H("Le carnet est à elle aussi. Je l'ai perdu vers 21h, j'ai couru tout le quai."),H("Vous l'avez ouvert ?")],c:[["Juste la dernière page, pour trouver à qui le rendre.","i4t",{t:0},"!"],["Non, jamais. Je l'ai à peine touché.","i4l",{l:1}]]},
i4t:{m:[H("Merci de me le dire."),H("C'est rare, l'honnêteté, un jeudi soir.")],x:"i5"},
i4l:{m:[H("D'accord."),H("Alors vous n'avez pas vu ce qui est écrit sous le numéro."),H("Ou alors vous l'avez vu, et vous préférez ne pas me le dire.")],c:[["Si, j'ai lu. Pardon, j'ai menti. J'avais peur que vous ne me fassiez plus confiance.","i5",{l:0}],["Je vous jure, je n'ai vu qu'un numéro.","i5",{t:-2}]]},
i5:{m:[H("Où êtes-vous, là ?")],c:[["Sur le banc, face au tableau des départs. Je ne bouge pas.","i6",{t:1},"!"],["Je peux vous le poster demain, si c'est plus simple.","i5x",{t:-1}]]},
i5x:{m:[H("Non."),H("Pas demain. Demain, je n'aurai peut-être plus le courage de le rouvrir.")],c:[["Alors j'attends. Prévenez-moi quand vous arrivez.","i6",{t:1}]]},
i6:{m:[H("Sous l'horloge ? Avec une plaque à moitié arrachée au-dessus ?"),N("Tu lèves la tête. Une plaque de laiton pend, arrachée d'un seul côté.")],c:[["Oui. Exactement celui-là. Comment vous le savez ?","i7",{t:1}],["Oui, c'est un banc comme les autres.","i7",{t:-1}]]},
i7:{m:[H("Parce que c'est là qu'elle m'a dit au revoir."),H("Je suis dans le RER, je descends dans vingt minutes. Ne bougez pas, s'il vous plaît.")],c:[["Je reste. Je ne toucherai plus au carnet, promis.","i7a",{t:2}],["Je vous attends, mais je préfère garder le carnet fermé.","i7b",{t:1}]]},
i7a:{m:[H("Merci. Je ne sais pas pourquoi, mais j'avais peur que vous changiez d'avis."),N("Tu ranges le carnet dans ton sac, sans l'ouvrir de nouveau. Pour la première fois de la soirée, tu ne regardes plus le tableau des départs.")],x:"i8"},
i7b:{m:[H("Vous avez raison. Il y a déjà assez de choses que je n'ai pas su respecter."),N("Tu poses le carnet bien à plat sur tes genoux et tu gardes les mains dessus, comme pour l'empêcher de s'envoler.")],x:"i8"},
i8:{m:[N("23h09. Le carnet est posé sur tes genoux. La couverture est tiède, comme si quelqu'un venait de le lâcher."),N("Vingt minutes. Un banc. Un carnet qui n'est pas à toi.")],c:[["Le garder fermé. Ce n'est pas à toi.","i10",{t:1},"!"],["Lire une page. Une seule.","i9",{r:1},"!"]]},
i9:{m:[N("Page 12, écriture penchée : « 3 mars. Je lui ai dit que j'allais bien. C'est la seule chose que je sais encore faire : mentir joliment. »"),N("En dessous, plus petit : « L. m'attend à 19h. Je lui dirai ce soir. Ou pas. »"),N("Tu refermes le carnet trop vite. Tu as l'impression d'avoir volé quelque chose.")],x:"i10"},
i10:{m:[H("Au fait, je m'appelle Inès. Vous m'avez donné votre prénom, c'est la moindre des choses."),K(),H("Je crois que j'ai envie de vous parler pendant ce temps-là. Ça vous va ?")],c:[["Ça me va. Je n'ai nulle part où être.","i11",{t:1}],["Pas trop longtemps, j'ai un truc demain matin.","i11",{t:-1}]]},
i11:{m:[H("Et vous, qu'est-ce que vous faisiez gare de Lyon à cette heure-là ?")],c:[["Je rentrais d'un dîner que j'ai fui. Je fuis souvent les dîners où il faut faire semblant.","i12",{t:2,v:1}],["Je rentrais du travail. Rien de passionnant.","i12",{}]]},
i12:{j:s=>s.v?"i12a":"i12b"},
i12a:{m:[H("Faire semblant."),H("C'est exactement ce que Camille écrivait dans son carnet.")],x:"i13"},
i12b:{m:[H("Ah. D'accord.")],x:"i13"},
i13:{m:[H("Elle, elle faisait semblant avec talent. Moi, je n'ai jamais su."),H("Les gens disaient : « Camille est toujours de bonne humeur. »"),H("Ils n'ont jamais vu ses carnets.")],c:[["Les carnets, c'est là qu'on dit ce qu'on ne dit pas.","i13c",{t:2}],["Elle avait peut-être besoin que les autres soient tranquilles.","i13c",{t:1}],["Un carnet, c'est une chance. Le mien finirait à la poubelle.","i13c",{t:1}]]},
i14:{m:[N("23h31. Le tableau annonce le dernier train pour Marseille."),H("Je suis arrivée. Je vous vois. La personne au bonnet gris, avec mon carnet sur les genoux."),H("Je suis à vingt mètres, devant la boulangerie fermée. Je n'arrive pas à avancer.")],c:[["Je me lève et je lève le carnet bien haut, comme un idiot.","i15",{t:1,h2:1},"!"],["Je reste assis. Je ne veux pas vous faire peur.","i15",{t:1,h2:0}]]},
i15:{j:s=>s.h2?"i15a":"i15b"},
i15a:{m:[H("Ne levez pas le carnet, on dirait un signal de détresse."),H("(Je rigole. Ça fait longtemps. C'est bizarre.)")],x:"i16"},
i15b:{m:[H("Merci. Si vous aviez bougé, je crois que j'aurais fui.")],x:"i16"},
i16:{m:[H("Avant de venir, je dois vous dire quelque chose. Sinon je ne bougerai pas."),H("Camille est morte il y a quatorze mois."),H("« Écris-moi quand même », elle l'a écrit la veille. Elle voulait que quelqu'un le fasse, un jour."),H("Moi, je n'ai jamais pu. C'est vous qui l'avez fait.")],c:[["Je suis désolé. Je ne sais pas quoi dire, alors je reste là, sur ce banc.","f",{t:2}],["Comment est-ce qu'elle est morte ? Si vous voulez en parler.","f",{t:-1}],["Tout va s'arranger, vous verrez.","f",{t:-2}]]},
f:{j:s=>s.t>=12?(s.r?"g2":"g1"):s.t>=6?"m1":"z1"},
g2:{m:[H("Vous avez lu la page 12, je me trompe pas ?"),H("Ça se voit à votre façon de le tenir. Je ne vous en veux pas."),H("Vous avez vu le « L. », forcément. Moi aussi, je me demande depuis quatorze mois qui c'est.")],x:"g1"},
g1:{m:[H("Je viens. Ne bougez pas."),N("Des pas sur le carrelage. Tu lèves la tête."),H("On ouvre la dernière page ensemble ? Je veux savoir ce que ça fait de la lire à quelqu'un."),H("On peut se tutoyer ? Je crois qu'on a passé le cap.")],k:"Fin 1 · Le deuxième message",x:"x0"},
m1:{m:[H("Merci. Vraiment. Mais je ne peux pas encore m'asseoir à côté de quelqu'un ce soir."),H("Posez le carnet sur le banc, je viens le chercher quand vous serez parti."),H("Je peux vous réécrire ? Pas pour le carnet. Pour qu'il y ait un message de plus dans ce téléphone.")],k:"Fin 2 · Un message de plus",x:"x0"},
z1:{m:[H("Merci d'avoir rapporté le carnet."),H("Vous êtes quelqu'un de gentil. Vraiment."),H("Mais ce soir, j'avais besoin de quelqu'un qui reste, pas de quelqu'un qui passe."),N("Elle récupère le carnet. Elle ne se retourne pas.")],k:"Fin 3 · Gentil, vraiment",x:"x0"},
q0:{w:"pluie",m:[N("Samedi, 14 h 12. Tu es chez toi, en train de ranger ton appartement. Dehors, la pluie tape contre les vitres."),N("Un SMS arrive d'un numéro inconnu. Aucun message précédent, aucun nom enregistré."),H("Dis-moi juste si je dois entrer. Je suis devant l'église et je n'arrive plus à ouvrir la portière.")],c:[["Je crois que tu t'es trompée de numéro. Tu es en sécurité, là ?","q1b",{care:1}],["Mauvais numéro. Mais si tu es en danger, appelle les secours ou quelqu'un sur place.","q1c",{bound:1,practical:1}],["Je ne sais pas qui tu es, mais je peux rester le temps que tu contactes quelqu'un que tu connais.","q1e",{care:1,bound:1}]]},
q1b:{m:[H("Oh mon Dieu. Oui, tu as raison : je me suis trompée de numéro. Pardon. Je voulais écrire à Marion, ma meilleure amie."),H("Je suis dans ma voiture, devant l'église. Je ne suis pas en danger, je panique juste et j'ai envoyé ça au mauvais contact."),H("Tu n'as aucune raison de m'aider. Je vais arrêter de t'embêter.")],c:[["Tu ne m'embêtes pas. Je peux rester un instant, mais je ne sais pas ce qui se passe.","q1f",{care:1,honest:1}],["D'accord. Je te laisse contacter Marion. Bon courage.","qz",{bound:1}],["Avant que tu partes : est-ce que tu veux que j'appelle quelqu'un sur place ?","q1c",{practical:1,care:1}]]},
q1c:{m:[H("Merci, mais non. Je viens de comprendre que j'ai écrit au mauvais numéro. Je ne suis pas en danger, et je ne veux pas te demander d'intervenir dans quelque chose que tu ne connais pas."),H("Je vais appeler ma cousine. Elle est à l'intérieur de l'église.")],c:[["Bonne idée. Appelle-la plutôt que de compter sur un inconnu.","qz",{practical:1,bound:1}],["Je peux attendre que tu me confirmes que tu l'as jointe, si ça te rassure.","q1e",{care:1}]]},
q1e:{m:[H("C'est gentil. Je m'appelle Lou. Enfin, je n'aurais probablement pas dû te donner mon prénom comme ça, vu que je t'ai écrit par erreur."),H("Je vais appeler ma cousine. Je voulais juste envoyer à Marion : « Je suis devant l'église, j'arrive pas à sortir de la voiture. »")],c:[["Tu n'as pas besoin de m'expliquer. Va appeler ta cousine.","qz",{bound:1,care:1}],["Si tu veux parler deux minutes en attendant, je peux écouter, mais je ne vais pas te pousser à raconter ta vie.","q1f",{care:1,honest:1}]]},
q1f:{m:[H("Merci. Je vais essayer d'être claire : je me suis trompée de numéro, je cherchais Marion. Tu n'es pas censé être mêlé à ça."),H("Elle se marie aujourd'hui. Je suis sa demoiselle d'honneur, et le marié est mon ex. Je pensais pouvoir gérer, mais je suis devant la porte depuis dix minutes."),H("Je ne te demande pas de régler ça. Je crois que j'avais juste besoin d'une réponse avant de réussir à appeler quelqu'un qui me connaît.")],c:[["Tu as déjà quelqu'un sur place. Qu'est-ce qui t'empêche de contacter ta cousine ?","q2a",{ask:1,practical:1}],["Tu peux me dire ce qui te fait le plus peur, si tu veux. Je ne déciderai pas à ta place.","q2b0",{care:1,agency:1}],["Je préfère ne pas devenir ton confident par accident. Appelle Marion ou ta cousine ; c'est eux qui peuvent vraiment t'aider.","q2d",{bound:1,practical:1}]]},
q2:{m:[H("Non, pas une dispute. Elle m'a demandé hier si j'arriverais à l'heure. J'ai répondu oui, comme si j'en étais certaine."),H("Elle se marie aujourd'hui. Je suis censée être à côté d'elle dans vingt minutes, et je n'arrive même pas à ouvrir la portière.")],c:[["Pourquoi tu ne veux pas entrer ?","q2c",{ask:1}],["Tu n'as pas à tout raconter à quelqu'un que tu ne connais pas. Appelle quelqu'un sur place.","q2d",{bound:1,practical:1}]]},
q2a:{m:[H("Ma cousine est à l'intérieur. Je pourrais l'appeler, mais elle m'a vue faire semblant d'aller bien pendant des semaines."),H("Je crois que j'ai honte qu'elle découvre que je ne gère pas du tout. Et je sais que tu es un inconnu, c'est précisément pour ça que je me suis sentie capable d'écrire.")],c:[["La honte est compréhensible, mais elle ne peut pas deviner ce dont tu as besoin. Écris-lui une phrase simple.","q2c",{practical:1,agency:1}],["Tu peux lui dire que tu as besoin d'elle sans raconter toute l'histoire tout de suite.","q2d",{care:1,practical:1}]]},
q2b0:{m:[H("Marion se marie dans vingt minutes. Je suis sa demoiselle d'honneur."),H("Le marié, Adrien, c'est mon ex. On s'est séparés il y a presque deux ans. Je pensais que c'était réglé."),H("Je ne sais pas si c'est lui qui me fait mal, ou le fait de voir tout le monde passer à la suite sans moi.")],c:[["Tu as encore des sentiments pour Adrien ?","q2c",{ask:1}],["C'est difficile de voir une ancienne vie devenir la vie de quelqu'un d'autre.","q2c",{care:1}],["Tu pourrais partir sans que ça fasse de toi une mauvaise amie. Mais c'est toi qui dois choisir.","q2d",{agency:1}]]},
q2c:{m:[H("Je ne sais pas si je l'aime encore. Je crois que je regrette surtout la version de moi qui pensait que tout était prévu."),H("On s'est séparés après une dispute idiote, en apparence. J'avais accepté un poste à Nantes. Il m'a dit qu'il ne voulait pas d'une relation à distance. J'ai refusé le poste pour lui, puis je lui en ai voulu de m'avoir laissée faire."),H("Six mois plus tard, il est parti quand même. Et Marion était là pour moi. C'est pour ça que j'ai dit oui aujourd'hui."),N("C'est la première fois qu'elle donne une vraie raison à sa panique. Elle n'a pas l'air soulagée pour autant.")],c:[["Tu as l'impression de lui devoir ta présence parce qu'elle t'a aidée ?","q3",{ask:1}],["Tu peux regretter ce choix sans faire payer Marion pour ce qu'Adrien t'a fait vivre.","q3",{t:-1,care:1}],["Je ne peux pas décider à ta place. Qu'est-ce que tu veux, toi, pour les dix prochaines minutes ?","q3",{t:1,agency:1}]]},
q2d:{m:[H("Tu as raison. J'ai une cousine dans la salle, elle sait que je suis fragile avec cette histoire."),H("Je pourrais lui écrire. Mais j'ai honte qu'elle me voie comme ça."),H("Je ne veux pas que tu sois obligé de gérer ça. Tu ne me dois rien." )],c:[["Je ne suis pas obligé, c'est vrai. Mais si tu veux, on peut réfléchir à un message simple pour ta cousine.","q3",{care:1,practical:1}],["Alors écris-lui maintenant. On peut s'arrêter là après, si tu préfères.","q3",{bound:1,practical:1}]]},
q3:{m:[H("Ce que je veux ? Je voudrais ne pas avoir à choisir entre être une bonne amie et me protéger."),H("Je sais que ce n'est pas une vraie alternative. Mais là, c'est comme ça que je le ressens."),H("Tu ferais quoi, toi ?")],c:[["Je demanderais à Marion cinq minutes en tête-à-tête, avant la cérémonie.","q3a",{practical:1,agency:1}],["Je resterais dans la voiture jusqu'à ce que mon corps arrête de paniquer, puis je déciderais.","q3b",{care:1,agency:1}],["Je partirais. Je ne crois pas qu'on doive se sacrifier pour prouver son amitié.","q3c",{advice:1}],["Je ne sais pas. Je ne te connais pas assez pour te conseiller honnêtement.","q3d",{honest:1,t:1}]]},
q3a:{m:[H("Lui demander cinq minutes, c'est exactement ce que je n'ose pas faire."),H("Marion mérite une journée parfaite. Je ne veux pas devenir le problème du jour."),H("Mais si je ne lui dis rien, je vais lui en vouloir de ne pas avoir deviné. C'est injuste, je le sais." )],c:[["Tu peux lui dire que tu l'aimes et que tu as besoin de cinq minutes, sans lui demander de changer sa journée.","q4a",{practical:1,care:1}],["Tu as peut-être besoin de lui dire la vérité, même si le moment n'est pas parfait.","q4b",{honest:1,agency:1}]]},
q3b:{m:[H("J'ai essayé de respirer. Ça aide un peu, mais j'entends la musique depuis la voiture et ça me donne envie de pleurer."),H("Je crois que je confonds 'attendre d'être calme' avec 'attendre de ne plus rien ressentir'. Ça risque d'être long." )],c:[["Alors donne-toi cinq minutes, pas une éternité. Après, tu choisis une action concrète.","q4a",{practical:1,agency:1}],["Tu peux aussi appeler ta cousine et lui demander de venir te voir dehors.","q4b",{practical:1,care:1}]]},
q3c:{m:[H("Une partie de moi a envie que tu me dises ça. Comme ça je pourrais partir et te rendre responsable de ma décision."),H("Pardon. C'est moche de dire ça, mais c'est vrai."),H("Je ne veux pas qu'un inconnu choisisse pour moi juste parce que j'ai peur." )],c:[["Tu as raison. Je ne vais pas choisir à ta place. Qu'est-ce qui te ferait le moins regretter ta décision demain ?","q4b",{agency:1,honest:1}],["Je ne peux pas savoir ce que tu regretteras. Je peux juste t'aider à faire un choix qui t'appartient.","q4a",{agency:1,care:1}]]},
q3d:{m:[H("C'est probablement la réponse la plus honnête que j'aie reçue aujourd'hui."),H("Tout le monde me donne des conseils depuis des semaines. Ma mère veut que je sourie, ma cousine veut que je parte, et Marion dit que je n'ai pas à faire semblant."),H("Je crois que je voulais entendre quelqu'un me dire quoi faire pour ne pas porter la décision toute seule." )],c:[["Je comprends. Mais je peux t'aider à comparer les options, pas vivre les conséquences à ta place.","q4a",{honest:1,agency:1}],["Si tu veux, dis-moi ce qui te fait le plus peur : entrer, partir, ou parler à Marion.","q4b",{ask:1,care:1}]]},
q4a:{m:[H("Ce qui me fait le plus peur, c'est que Marion me voie et comprenne immédiatement. Elle me connaît trop bien."),H("Elle m'a envoyé une photo de nos robes hier soir. La mienne est encore sur le siège passager, dans sa housse."),N("Un instant plus tard, une photo arrive.") ,N("Une photo : une robe bleu nuit sur un cintre, posée sur le siège passager. Sur le tissu, une petite étiquette écrite à la main : « Lou — à côté de moi »." )],c:[["La photo donne l'impression qu'elle t'a vraiment imaginée à ses côtés. Tu peux lui dire ce que tu ressens, sans lui demander de réparer quoi que ce soit.","q4c",{care:1,honest:1}],["Tu pourrais rendre la robe à ta cousine et partir. Tu n'as pas besoin de tout régler aujourd'hui.","q4d",{advice:1}],["Qu'est-ce que tu aimerais que Marion sache, si tu pouvais lui dire une seule chose ?","q4c",{ask:1,agency:1}]]},
q4b:{m:[H("J'ai envie de lui dire que je l'aime, mais que j'ai besoin qu'elle me voie comme je suis, pas comme la demoiselle d'honneur qui gère tout."),H("Je n'ai jamais su lui dire quand ça n'allait pas. Elle traversait déjà tellement de choses que je faisais la forte."),H("Je viens de taper un message à ma cousine : 'Tu peux sortir deux minutes ? Je ne vais pas très bien.' Je ne l'ai pas encore envoyé." )],c:[["Envoie-le. C'est un petit pas, pas une décision sur toute la journée.","q4c",{practical:1,agency:1}],["Avant d'envoyer, vérifie que c'est bien ce que tu veux demander. Tu as le droit de changer les mots.","q4d",{agency:1,honest:1}]]},
q4c:{m:[H("C'est envoyé."),N("Les trois petits points apparaissent, disparaissent, puis reviennent."),H("Elle répond : « J'arrive. Ne bouge pas. »"),N("Lou pose le téléphone sur ses genoux. Pour la première fois, elle n'a pas besoin de te demander quoi faire.")],c:[["Je peux rester là si tu veux, mais tu n'as pas besoin de me tenir au courant de tout.","q5",{care:1,bound:1}],["Va parler avec elle. Tu pourras décider de la suite après.","q5",{practical:1,agency:1}]]},
q4d:{m:[H("J'ai changé le message. J'ai écrit : « Je suis devant l'église. J'ai besoin de cinq minutes avec toi, si tu peux. »"),H("C'est moins dramatique. C'est plus vrai aussi."),N("Elle appuie sur envoyer. La réponse n'arrive pas tout de suite, et cette fois elle ne renvoie pas un autre message pour remplir le silence.")],c:[["Laisse-lui le temps de répondre. Tu as déjà fait ta part.","q5",{care:1,agency:1}],["Si elle ne répond pas, tu pourras choisir sans attendre qu'elle te donne la permission.","q5",{agency:1,honest:1}]]},
q5:{m:[N("Au loin, les cloches commencent à sonner. La pluie ralentit, mais le pare-brise reste couvert de gouttes."),H("Ma cousine arrive. Je la vois dans le rétroviseur, elle court avec un parapluie trop petit."),N("Lou t'envoie une dernière question avant d'ouvrir la portière."),H("Je ne sais toujours pas si je vais entrer. Mais je sais que je ne veux plus décider juste pour éviter d'avoir honte." )],c:[["Entre avec ta cousine, et donne-toi le droit de sortir si c'est trop.","qf",{agency:1,care:1,enter:1}],["Demande à Marion de venir dehors avant la cérémonie, même si ça retarde les choses.","qf",{honest:1,truth:1}],["Pars si c'est ce qu'il te faut. Mais envoie à Marion un message qui explique que tu l'aimes.","qf",{leave:1,care:1}],["Reste encore cinq minutes dans la voiture. Tu n'as pas à décider sous la pression des cloches.","qf",{wait:1}]]},
qf:{j:s=>s.truth&&s.t>=2?"qh":s.leave?"qz":s.enter&&s.care>=2?"qg":s.wait?"qm":s.enter?"qg":"qm"},
qg:{w:"pluie",m:[H("Je sors de la voiture. Ma cousine marche à côté de moi sans poser de questions."),N("Des pas résonnent sur les dalles mouillées. Une photo : la grande porte de l’église, avec le parapluie rouge de sa cousine au premier plan."),H("Je vais m'asseoir au fond. Je ne promets pas de sourire tout le temps, mais je vais essayer d'être là pour elle."),H("Merci de ne pas avoir décidé à ma place. Je vais ranger mon téléphone maintenant.")],k:"Fin 1 · Entrer sans faire semblant",x:"v0"},
qh:{w:"pluie",m:[H("Marion est sortie. Elle m'a prise dans ses bras avant que je puisse parler."),H("Je lui ai dit la vérité : que j'étais heureuse pour elle, mais que revoir Adrien réveillait une partie de ma vie que je croyais terminée."),H("Elle m'a dit qu'elle aurait préféré le savoir plus tôt. Elle était blessée, mais pas en colère."),N("Une photo : deux mains serrées sous un parapluie rouge, devant la porte de l'église."),H("Je vais entrer avec elle. Pas parce que je lui dois ça. Parce qu'on a enfin parlé franchement.")],k:"Fin 2 · La vérité avant la cérémonie",x:"v0"},
qm:{m:[H("Je reste encore un peu dans la voiture. Ma cousine s'assoit à côté de moi, sans essayer de me convaincre."),H("Je ne sais pas si j'entrerai. J'ai dit à Marion que j'avais besoin de temps et que je l'aimais."),H("Ce n'est pas une fin parfaite. Mais c'est ma décision, pour une fois.")],k:"Fin 3 · Prendre le temps",x:"v0"},
qz:{m:[H("Je pars. Je ne me sens pas fière, mais je ne suis plus en train d'attendre que quelqu'un m'autorise à le faire."),H("J'ai écrit à Marion : « Je t'aime. Je n'arrive pas à entrer aujourd'hui. Je t'expliquerai quand je pourrai. Je suis désolée de ne pas te l'avoir dit avant. »"),N("La voiture s'éloigne de l'église. Le téléphone reste silencieux, et Lou ne relance pas la conversation."),H("Merci d'avoir répondu, même si tu n'étais pas la personne que je cherchais.")],k:"Fin 4 · Partir en assumant",x:"v0"}
};
Object.assign(S,{
p0:{w:"mer",m:[N("Île de Kerlo, 6h40. Le ferry s'éloigne dans la brume. Il ne reviendra que mardi."),N("Sur la table de la cuisine, un mot à l'encre bleue : « Si ça coince, écris-moi. E. ». Dessous, un numéro."),N("Le chauffe-eau est éteint. La radio grésille. Le phare, lui, a l'air de t'attendre.")],c:[["Lui écrire : « Bonjour, je suis votre remplaçant. Ça coince déjà. »","p1",{t:1}],["Te débrouiller seul. Écrire, ce serait avouer que tu n'y arrives pas.","p1b",{}]]},
p1:{m:[H("Déjà ? Moi, j'ai tenu trois semaines avant d'écrire à quelqu'un."),H("Je m'appelle Eliott, au fait. Le « E. » du mot.")],c:[["Merci. Je vais essayer, mais je te préviens : je ne suis pas bricoleur.","p1a",{t:1}],["Tu dis ça comme si cette île avait déjà essayé de te tuer avec un chauffe-eau.","p1c",{t:2}]]},
p1a:{m:[H("Bonne nouvelle : le fusible ne demande pas de diplôme. Mauvaise nouvelle : la radio, elle, a du caractère."),K(),H("Le fusible est derrière la porte bleue de la cave. Pour la radio, deux petits coups sur le boîtier. Ne la regarde pas de travers, elle sent la peur.")],x:"p2"},
p1c:{m:[H("Pas le chauffe-eau. La radio, peut-être. Elle grésille même quand elle est éteinte."),K(),H("Le fusible est derrière la porte bleue de la cave. Pour la radio, deux petits coups sur le boîtier. Ne la regarde pas de travers, elle sent la peur.")],x:"p2"},
p1b:{m:[N("Trois heures plus tard : des doigts bleus, une bouilloire qui siffle, toujours pas d'eau chaude."),N("Ton téléphone vibre. Tu n'as rien demandé."),H("Le fusible du chauffe-eau saute tous les hivers. Porte bleue, dans la cave."),H("Tu es de ceux qui ne demandent jamais, toi."),H("Eliott, au fait. Le « E. » du mot."),K()],x:"p2"},
p2:{m:[N("Tu montes les dernières marches de la tour. Le vent tire sur ta veste et le téléphone vibre contre ta paume."),H("Dis-moi ce que tu vois, là-haut. J'ai besoin de savoir qu'elle est toujours là.")],c:[["Du vent, des goélands, un phare plus petit que prévu. Et très beau, bizarrement.","p2b",{t:2,c:1}],["Un caillou avec une tour dessus. Je ne vois pas ce qu'on peut aimer là-dedans.","p2b",{t:-1}]]},
p3:{j:s=>s.c?"p3a":"p3b"},
p3a:{m:[H("« Plus petit que prévu, et très beau. »"),H("C'est ce que je disais à tout le monde, la première semaine. Ça fait deux ans que personne ne me le dit comme ça.")],x:"p3x"},
p3b:{m:[H("Laisse-lui un mois. Elle finit toujours par rentrer sous la peau.")],x:"p3x"},
p4:{w:"mer",m:[N("L'après-midi, la tempête se lève. Dans le registre de la station, la dernière page est au crayon : « 19 déc. Ne pas oublier de lui dire. »"),N("Pas de nom. Pas de suite.")],c:[["Demander à Eliott de qui il s'agit.","p5",{q:1,t:1},"De qui tu parles, exactement ?"],["Ne rien dire. Ce n'est pas ton histoire.","p5",{},"!"]]},
p5:{j:s=>s.q?"p5a":"p5b"},
p5a:{m:[H("Tu as lu le registre."),H("Je savais que quelqu'un le ferait. J'aurais dû arracher la page."),H("Elle s'appelle Maëlle. Elle fait la traversée tous les mardis. Elle ne sait pas que j'ai quitté l'île.")],x:"p6"},
p5b:{m:[N("Le soir, il t'écrit sans que tu aies rien demandé."),H("Je te dois un début d'explication."),H("Il y a une femme sur le ferry du mardi. Maëlle. Elle ne sait pas que j'ai quitté l'île.")],x:"p6"},
p6:{m:[H("Mardi, c'est toi qu'elle verra descendre. Elle croira que c'est moi. Ou elle ne croira plus rien."),H("Je ne te demande pas de mentir. Juste de ne pas la laisser seule sur le quai."),N("Tu relis le message. Il ne te demande pas de réparer sa vie, mais il te place au milieu d'une vérité qui ne t'appartient pas.")],c:[["D'accord. Je serai sur le quai. Mais je lui dirai la vérité.","p6b",{h:1,t:2}],["Je ne peux pas me mêler de ça. Dis-lui toi-même.","p6b",{t:-1}],["D'accord. Je serai Eliott, juste pour mardi.","p6b",{l:1}]]},
p7:{j:s=>s.h?"pg":s.l?"pl":"pz"},
pg:{m:[H("Merci."),H("Je n'ai pas le courage. Toi, tu l'as dès le premier jour. C'est bizarre, d'être remplacé par quelqu'un de plus brave que soi.")],k:"La vérité sur le quai",x:"k0"},
pl:{m:[H("Merci. Je sais que c'est beaucoup demander."),H("Ne dis pas qu'elle me ressemble. Elle n'a jamais voulu qu'on la compare.")],k:"Le prête-nom",x:"k0"},
pz:{m:[H("Tu as raison. C'est à moi de le faire."),H("Je ne sais juste pas quand.")],k:"Le silence d'Eliott",x:"k0"}
});
Object.assign(S,{
x0:{j:s=>{s.b=s.t;return s.e&&s.e[4]=="1"?"x1":s.e&&s.e[4]=="2"?"x1b":"x1c"}},
x1:{w:"nuit",m:[N("Trois jours après la gare. Vous êtes restés sur le banc jusqu'à ce que le vigile vous demande de partir."),Sy("Inès t'écrit maintenant depuis son propre numéro, enregistré ce soir-là."),H("Je n'ai pas dormi. Je t'écris avant de changer d'avis.")],x:"x2"},
x1b:{w:"nuit",m:[N("Huit jours de silence. Puis un jeudi, 23h04, un numéro que tu ne connais pas."),Sy("Ce n'est plus le téléphone de Camille. C'est celui d'Inès."),H("C'est moi. J'ai pris une autre carte SIM. Le téléphone de Camille est dans un tiroir, éteint."),H("On peut se tutoyer ? Je sais, c'est brusque. Mais je viens de passer huit jours à t'écrire dans ma tête."),H("Je n'aurais pas dû t'écrire. Mais je n'ai personne d'autre à qui le dire.")],x:"x2"},
x1c:{w:"nuit",m:[N("Dix jours. Tu as supprimé son numéro deux fois, et tu l'as retrouvé deux fois."),Sy("Un nouveau numéro. Ce n'est plus le téléphone de Camille."),H("C'est Inès. J'ai pris un autre numéro."),H("Je te tutoie. Dix jours de silence, ça vaut bien un tutoiement."),H("Je t'avais dit que tu étais gentil. C'était injuste : tu étais surtout resté à ta place."),H("J'ai besoin de quelqu'un, ce soir. Ça tombe sur toi.")],x:"x2"},
x2:{m:[H("J'ai rouvert le carnet à l'envers. Sous le rabat de la couverture, il y a un numéro écrit au crayon, presque effacé. Et un prénom : Léo."),H("Le « L. » de la page 12, c'est lui, j'en suis sûre."),H("Elle a noté en dessous : « Appelle-le si je n'y arrive pas. » Y arriver à quoi ?")],c:[["On l'appelle ensemble, ce soir. Je reste avec toi sur la ligne.","x3",{t:2}],["Cherche d'abord qui il est. Un nom, une photo, n'importe quoi.","x2v",{t:1}],["Laisse tomber. Remuer le passé ne ramène personne.","x2n",{t:-2}]]},
x2v:{m:[N("Tu cherches avec elle pendant une heure. Trois Léo possibles. Elle retrouve enfin une photo de Camille et Léo, prise sur une plage, un été où elle riait aux éclats. Elle te l'envoie."),H("Elle ne riait pas comme ça sur les photos que j'ai."),H("Ok. Je l'appelle. Maintenant, avant de changer d'avis.")],x:"x3"},
x2n:{m:[H("Peut-être."),H("Mais c'est la seule chose qu'elle m'ait jamais demandée.")],c:[["Tu as raison, pardon. On l'appelle.","x3",{t:2}]]},
x3:{m:[N("22h40. À chaque sonnerie, elle t'envoie un chiffre : « 1 ». « 2 ». « 3 »."),H("Il a décroché."),H("Il a dit : « Je savais que quelqu'un finirait par appeler. »"),H("Il était avec elle le soir de l'accident. Il n'a jamais osé me le dire. Je ne sens plus mes mains.")],c:[["Respire. Je reste là, aussi longtemps qu'il parlera.","x3b",{t:2}],["Il a peut-être menti pendant tout ce temps. Méfie-toi.","x3b",{t:-1}]]},
x3b:{m:[H("Il dit qu'elle n'allait pas bien. Qu'elle avait peur de me le dire, parce que je croyais toujours qu'elle allait bien."),H("Quatorze mois que je me répète que je l'aurais vu.")],c:[["Tu ne pouvais pas le voir. Elle faisait semblant avec talent, tu me l'as dit.","x3c",{t:2}],["Tu ne l'as pas vu. Mais maintenant tu sais.","x3c",{t:1}],["Tu aurais dû poser plus de questions.","x3c",{t:-2}]]},
x4:{m:[H("Il demande à me voir samedi. Gare de Lyon, le même banc. Il dit qu'il a quelque chose à me donner."),H("Tu viendrais ?")],c:[["Oui. Je serai sur le banc avant toi.","x5",{t:2}],["Je serai là, mais à distance. C'est ta rencontre, pas la mienne.","x5",{t:1}],["Je ne sais pas si c'est ma place.","x5",{t:-1}]]},
x5:{j:s=>s.t-s.b>=9?"xg":s.t-s.b>=5?"xm":"xz"},
xg:{m:[H("Merci. Vraiment."),H("À trois sur un banc, il reste moins de place pour le silence.")],k:"Trois sur un banc",x:"y0"},
xm:{m:[H("D'accord. Reste à distance, mais reste."),H("Je crois que j'ai besoin de savoir que quelqu'un regarde.")],k:"À vingt mètres",x:"y0"},
xz:{m:[H("Je comprends."),H("J'irai seule. Je ferai comme j'ai toujours fait.")],k:"Le banc vide",x:"y0"},
y0:{j:s=>{s.b=s.t;return s.e&&s.e[0]=="T"?"y1":s.e&&s.e[0]=="À"?"y1b":"y1c"}},
y1:{w:"gare",m:[N("Samedi, 15h. Gare de Lyon. Léo est plus jeune que tu l'imaginais. Il tient une enveloppe kraft à deux mains, comme un objet fragile."),N("Il s'assoit à l'autre bout du banc. Il ne dit rien pendant longtemps, puis il tend l'enveloppe avant que ses mains ne changent d'avis."),H("Il me l'a tendue. Je n'ose pas l'ouvrir. Reste à côté de moi.")],x:"y2"},
y1b:{w:"gare",m:[N("Samedi, 15h. Tu es à vingt mètres. Tu vois Inès, le dos droit, prendre une enveloppe des mains d'un homme."),H("C'est une lettre de Camille. Viens. S'il te plaît, viens.")],x:"y2"},
y1c:{w:"gare",m:[N("Samedi. Tu n'es pas venu. À 15h12, ton téléphone s'allume."),H("Il m'a donné une lettre de Camille. J'aurais voulu que tu sois là. Je n'ose pas l'ouvrir seule.")],x:"y2"},
y2:{m:[H("Il m'a dit : « Elle m'a demandé de te la donner le jour où tu m'appellerais. Pas avant. »"),H("Elle savait que j'appellerais. Quatorze mois, et elle savait."),H("Elle est datée de la veille de sa mort. Je te la lis ? Ou je la garde pour moi ?")],c:[["Lis-la. Je t'écoute, le temps qu'il faudra.","y3",{t:2}],["Garde-la. Certaines choses ne se partagent pas.","y3",{t:1}]]},
y3:{m:[H("« Inès. Si tu lis ça, c'est que tu as fini par appeler Léo. Bravo. »"),H("« Je t'ai dit que j'allais bien. C'est le plus gros mensonge que je t'aie fait, et je mens mal quand ça compte. »"),H("« Je ne voulais pas que tu portes ça seule. Alors j'ai laissé mon numéro dans un carnet, avec une phrase, pour que quelqu'un puisse écrire. »"),H("« Si quelqu'un écrit un jour, réponds-lui. Même si ce n'est pas moi. »"),H("Quelqu'un a écrit. C'était toi.")],c:[["Je suis content d'avoir tapé ce numéro. Même si c'était par hasard.","y3b",{t:2}],["Je ne sais pas quoi dire.","y3b",{}],["Je ne veux pas prendre la place de Camille.","y3b",{t:1}]]},
y4:{m:[H("Personne ne prend la place de personne."),H("Mais il y a une place libre à côté de moi, sur ce banc. Je ne sais pas si tu veux t'y asseoir.")],c:[["Je m'assois.","y5",{t:3},"!"],["Je viens demain. Ce soir, tu as besoin d'être avec elle.","y5",{t:1}],["Je ne suis pas sûr d'être la bonne personne.","y5",{t:-2}]]},
y5:{j:s=>s.t-s.b>=8?"yg":s.t-s.b>=4?"ym":"yz"},
yg:{m:[H("Alors assieds-toi."),N("Le banc est tiède. Elle pose la tête sur ton épaule, et tu comprends qu'il n'y avait jamais eu de mauvais numéro.")],e:["Le banc tiède","Un carnet, une lettre, un nouveau numéro enregistré sous un seul mot : « Reste ».\n\nÀ suivre : Chapitre 2."]},
ym:{m:[H("Demain, alors. Je garde la place."),H("Elle disait toujours : « Les bonnes personnes arrivent par accident. »")],e:["Demain","Tu rentres en métro avec le goût de ses mots. Demain n'a jamais semblé aussi proche.\n\nÀ suivre : Chapitre 2."]},
yz:{m:[H("D'accord."),H("Alors merci d'avoir répondu à sa place. C'est déjà énorme.")],e:["Merci quand même","Elle plie la lettre et la range dans le carnet. Tu te demanderas longtemps ce qu'il y avait écrit après la dernière ligne.\n\nÀ suivre : Chapitre 2."]},
v0:{j:s=>{s.b=s.t;return s.e&&s.e[4]=="1"?"v1":s.e&&s.e[4]=="2"?"v1b":"v1c"}},
v1:{w:"pluie",m:[N("17h02. La cérémonie est finie, les cloches sonnent encore. Elle t'écrit depuis les marches de l'église."),H("Je suis restée jusqu'au bout. Adrien m'a vue, au fond. Il a souri, comme on sourit à quelqu'un qu'on a déjà perdu.")],x:"v2"},
v1b:{w:"pluie",m:[N("Le lendemain matin. Rien depuis la veille au soir."),H("Je n'ai pas dormi. Marion m'a appelée onze fois. Je n'ai décroché aucune.")],x:"v2"},
v1c:{w:"pluie",m:[N("Une semaine plus tard, un numéro que tu connais déjà."),H("C'est Lou. Je ne t'ai dit ni merci ni pardon, l'autre jour. Les deux, je crois.")],x:"v2"},
v2:{m:[H("On peut se tutoyer ? Après tout ce que je t'ai raconté devant une église, ça devient ridicule."),H("Marion sait que j'étais garée devant. Elle veut me voir deux heures, chez elle. Avec Adrien.")],c:[["Vas-y. Mais pas pour eux, pour toi.","v2b",{t:2}],["Dis non. Tu ne leur dois rien.","v2b",{t:-1}],["Vas-y. Je reste sur la ligne, si tu veux.","v2b",{t:1}]]},
v3:{m:[N("Dans la cage d'escalier de Marion, elle t'écrit à chaque étage."),H("Quatrième. Je monte."),H("Adrien est là, cravate défaite, cernes. Marion pleure à côté de lui. Elle dit : « J'avais peur que tu ne viennes pas. »"),H("Et moi, je ne ressens rien. Rien du tout. C'est ça qui est affreux.")],c:[["Rien, ça peut être de la paix. Pas de l'indifférence.","v3b",{t:2}],["Alors tu n'as plus rien à prouver. Tu peux partir.","v3b",{t:1}]]},
v4:{m:[H("Marion m'a donné une enveloppe. Elle a acheté le billet il y a six mois : Lisbonne, demain 6h10, à mon nom."),H("« Pour le jour où tu iras mieux. » Avant même qu'on parle de mariage."),H("Lisbonne, c'est la ville dont je lui parlais tout le temps. Celle où je voulais aller avec Adrien."),H("Elle me donne la ville, sans lui. Je suis restée sans voix.")],c:[["Pars. Tu mérites un endroit où personne ne connaît ton histoire.","v5",{t:2}],["Reste. Fuir ne règle rien.","v5",{t:-1}],["Pars. Et envoie-moi une photo de ce que tu vois.","v5",{t:2}]]},
v5:{j:s=>s.t-s.b>=8?"vg":s.t-s.b>=4?"vm":"vz"},
vg:{m:[H("Je pars demain. Je ne sais pas pourquoi je te le dis à toi."),H("Si. Je sais.")],k:"Départ 6h10",x:"w0"},
vm:{m:[H("Je ne sais pas encore. Je vais dormir dessus.")],k:"Une nuit pour décider",x:"w0"},
vz:{m:[H("Tu as peut-être raison. Je vais rentrer chez moi.")],k:"Le billet dans le tiroir",x:"w0"},
w0:{j:s=>{s.b=s.t;return s.e[0]=="D"?"w1":s.e[0]=="U"?"w1b":"w1c"}},
w1:{w:"gare",m:[N("Aéroport, 5h32. Elle t'écrit entre deux portiques."),H("J'ai failli faire demi-tour au contrôle. Une dame m'a dit « ça va aller », et je n'ai pas osé lui dire que je n'y croyais pas.")],x:"w1d"},
w1b:{w:"nuit",m:[N("3h07. Elle ne dort pas non plus."),H("J'ai ouvert le sac. Je l'ai refermé. Je l'ai rouvert. Le vol est dans trois heures et je suis en pyjama sur mon lit."),H("Je vais y aller, je crois. Mais pas sans te le dire.")],x:"w1d"},
w1c:{w:"nuit",m:[N("Trois jours plus tard, minuit passé."),H("J'ai racheté un billet. Même vol, même heure, demain. Le premier est périmé, comme moi."),H("Dis-moi quelque chose de gentil. J'ai de la place dans mes bagages.")],x:"w1d"},
w2:{m:[H("Dis-moi pourquoi tu m'as répondu, le premier jour. Sérieusement.")],c:[["Parce que ton message ressemblait à un appel au secours, et que j'avais le temps.","w3",{t:1}],["Parce que même écrite, ta voix m'a donné envie de connaître la suite.","w3",{t:2}],["Je ne sais pas. Un coup de chance.","w3",{t:-1}]]},
w3:{m:[H("Avec Adrien, c'était toujours moi qui écrivais en premier. Pendant quatre ans."),H("Toi, quand je ne réponds pas, tu ne me relances pas. Tu attends. Ça m'a fait peur. Et en même temps...")],c:[["Et en même temps ?","w3b",{t:1}],["Je ne te relance pas parce que je ne veux pas te mettre la pression.","w3b",{t:2}]]},
w4:{w:"gare",m:[N("L'embarquement ouvre dans quarante minutes. Elle est debout devant le tableau des départs."),H("Si je monte, je pars pour de vrai. Si je reste, je rentre dans ma vie d'avant."),H("Dis-moi quoi faire. Je ferai ce que tu dis. Promis.")],c:[["Monte. Mais décide-toi dans l'escalier, pas à cause de moi.","w5",{t:3}],["Monte. Je t'attends de l'autre côté.","w5",{t:2}],["Reste. Je viens te chercher.","w5",{t:0}]]},
w5:{j:s=>s.t-s.b>=11?"wg":s.t-s.b>=6?"wm":"wz"},
wg:{m:[N("Deux minutes plus tard, une photo : un escalier roulant, ses chaussures, le haut d'un hublot."),H("Je suis montée. Je n'ai pas fait semblant de sourire. Je pleure un peu, mais c'est de l'air frais.")],e:["Au-dessus des nuages","Elle atterrit à Lisbonne : « Il fait 22 degrés. Personne ne me connaît. Appelle-moi. »\n\nÀ suivre : Chapitre 2."]},
wm:{m:[H("Je reste dans la file. Je ne sais pas si je pars."),N("Elle ne répond plus pendant dix minutes. Puis :"),H("Je suis assise dans l'avion. Je n'ai pas osé te le dire avant.")],e:["Un siège côté hublot","Elle partira un peu de travers, un peu sans toi. Mais avec ton numéro.\n\nÀ suivre : Chapitre 2."]},
wz:{m:[H("Tu as raison. Je ne suis pas prête."),N("Le tableau des départs affiche : « Embarquement terminé ».")],e:["Embarquement terminé","Elle rentre. Toi, tu relis la conversation en cherchant la phrase qui aurait tout changé.\n\nÀ suivre : Chapitre 2."]},
k0:{j:s=>{s.b=s.t;return s.h?"k1":s.l?"k1b":"k1c"}},
k1:{w:"mer",m:[N("Mardi, 11h40. Le ferry est un point blanc sur une mer d'acier."),H("Tu es sur le quai ? Dis-moi qu'il y a du vent. Elle déteste quand il n'y en a pas.")],x:"k1d"},
k1b:{w:"mer",m:[N("Mardi, 11h40. Tu as emprunté le ciré d'Eliott. Il sent le sel et le tabac froid."),H("Mets la capuche. Elle reconnaîtra le ciré avant ton visage. C'est ça, le plan.")],x:"k1d"},
k1c:{w:"mer",m:[N("Mardi, 11h40. Tu n'as rien promis. Tu es quand même sur le quai, sans savoir pourquoi."),H("Tu es là ? Je n'osais pas te le demander une deuxième fois.")],x:"k1d"},
k2:{m:[N("Le ferry accoste. Une femme descend la passerelle en dernier, un sac de toile sur l'épaule. Elle cherche un visage. Pas le tien."),H("Décris-la-moi. Tout. Je veux savoir si elle a coupé ses cheveux.")],c:[["Elle les a courts. Elle a l'air fatiguée. Elle regarde partout, sauf devant elle.","k3",{t:2}],["Brune, la trentaine. Je ne vois pas ce que ça change.","k3",{t:-1}]]},
k3:{m:[N("Elle arrive devant toi. S'arrête. Son sourire s'éteint comme un phare qu'on débranche."),N("« Où est Eliott ? »")],c:[["(à voix haute) Il a quitté l'île, Maëlle. Il n'a pas eu le courage de te le dire lui-même.","k4",{t:2},"!"],["(à voix haute) Il est en mer. Il revient bientôt.","k4l",{t:-2,l:1},"!"],["(à voix haute) Appelle-le. Il t'attend.","k4",{t:1},"!"]]},
k4l:{m:[N("Elle te regarde longtemps. « Menteur. Il ne part jamais en mer le mardi. »")],c:[["(à voix haute) Pardon. Il est parti. Je ne savais pas comment te le dire.","k4",{t:1},"!"]]},
k4:{m:[N("Elle pose son sac. Elle regarde la mer plutôt que toi. « Depuis quand ? »"),H("Dis-lui que je suis désolé. Dis-lui ce que je ne sais pas dire.")],c:[["(à voix haute) Il m'écrit en ce moment. Il dit qu'il est désolé. Je peux te montrer.","k4c",{t:3},"!"],["(à voix haute) Ce n'est pas à moi de le dire.","k4c",{t:0},"!"]]},
k5:{j:s=>s.t-s.b>=9?"kg":s.t-s.b>=4?"km":"kz"},
kg:{m:[N("Tu lui tends le téléphone. Elle lit en silence, lentement, comme on décode une carte. Elle tape quelque chose, puis te le rend."),H("Elle a répondu : « Rejoins-moi à Kerlo avant le dernier ferry. Ou je viens te chercher. »"),H("Elle n'a jamais été douce. Elle a toujours été juste.")],k:"Le téléphone tendu",x:"o0"},
km:{m:[N("Elle reste un moment sans bouger."),H("Elle a pris le sentier de la falaise. Ne la suis pas. Laisse-lui la mer.")],k:"Le sentier de la falaise",x:"o0"},
kz:{m:[N("Elle remonte dans le ferry sans un mot. La passerelle se retire."),H("Elle est repartie ? Tu aurais pu lui donner ma lettre.")],k:"Le ferry reparti",x:"o0"},
o0:{j:s=>{s.b=s.t;return s.e[3]=="t"?"o1":s.e[3]=="s"?"o1b":"o1c"}},
o1:{w:"mer",m:[N("Nuit. La station, un poêle qui ronfle. Maëlle dort sur le canapé, le téléphone d'Eliott serré dans la main."),H("Elle dort ? Dis-moi qu'elle dort.")],x:"o2"},
o1b:{w:"mer",m:[N("Maëlle est revenue à la nuit tombée sans un mot. Elle est montée dans la salle de la lampe."),H("Elle est dans le phare ? Elle en a la clé depuis dix ans.")],x:"o2"},
o1c:{w:"mer",m:[N("Une semaine plus tard. Un mardi de plus. Tu attends au même endroit."),H("Elle ne viendra pas. Mais regarde quand même.")],x:"o2"},
o2:{m:[H("Il faut que je te dise le vrai début. Le registre, la page au crayon."),H("« Ne pas oublier de lui dire. » Je t'ai laissé croire que c'était une déclaration d'amour."),H("Ce que je dois lui dire, c'est ce que j'ai vu le 19 décembre. Un bateau sans feux. Je n'ai pas appelé les secours.")],c:[["Eliott. Qu'est-ce que tu as vu, exactement ?","o3",{t:2}],["Tu aurais dû appeler. Tu sais qu'on est tenu de le faire.","o3",{t:0}]]},
o3:{m:[H("Un bateau de pêche. Sans feux, trop près des Roches. J'ai cru qu'ils savaient ce qu'ils faisaient."),H("Le lendemain, on a retrouvé le Marie-Lou retourné. Celui de Tanguy."),H("Tanguy, c'est le frère de Maëlle.")],c:[["Tu n'aurais pas pu savoir.","o3b",{t:1}],["Tu dois le lui dire. Aujourd'hui.","o3b",{t:2}],["Tu lui as menti pendant deux mois.","o3b",{t:0}]]},
o4:{m:[H("Je sais que je dois lui dire. Je suis lâche, c'est tout."),H("Je te demande une dernière chose : lis-lui le registre. La page entière, pas ce qu'elle suppose.")],c:[["Je ne le ferai pas à ta place. Reviens et dis-le-lui toi-même.","o5",{t:2}],["Je le ferai. Mais je lui dirai que c'est toi qui me l'as demandé.","o5",{t:1}],["Je préfère ne pas être celui qui lui apprend ça.","o5",{t:-2}]]},
o5:{j:s=>s.t-s.b>=8?"og":s.t-s.b>=4?"om":"oz"},
og:{m:[H("Merci. Je prends le bateau demain. Seul. Je n'ai plus de ferry pour me cacher.")],e:["Le dernier ferry","Il arrive dans douze heures, avec un sac et une lettre. Tu as fait ce qu'il fallait : laisser la porte ouverte.\n\nÀ suivre : Chapitre 2."]},
om:{m:[H("Tu as raison. Le courage, c'est à moi de l'avoir. Pas à toi."),H("Dis-lui que j'arrive. Même si je ne sais pas encore quand.")],e:["J'arrive","Un message d'Eliott dans le noir : « Dis-lui que j'arrive. » Tu ne sais pas si c'est une promesse.\n\nÀ suivre : Chapitre 2."]},
oz:{m:[H("Je comprends."),H("Alors je lui écrirai. C'est tout ce que j'ai.")],e:["Une lettre sur le quai","Il y aura une lettre sur le quai mardi prochain. Elle ne sera pas pour toi, mais c'est toi qui la porteras.\n\nÀ suivre : Chapitre 2."]}
});
Object.assign(S,{
i13c:{m:[H("Je vous propose un jeu stupide. Une vérité contre une vérité. Rien de grave."),H("Je commence : je n'ai pas pleuré depuis quatorze mois. Pas une seule fois. Je dis aux gens que ça va, et ils me croient.")],c:[["Ma vérité : je n'ai pas appelé ma mère depuis six mois. J'ai peur qu'elle entende que ça ne va pas.","i13d",{t:2}],["Ma vérité : je suis nul aux dîners, aux jeux, aux gens en général.","i13d",{t:1}],["Je préfère ne pas jouer. Ce n'est pas le bon moment.","i13e",{t:-1}]]},
i13d:{m:[H("Merci."),H("C'est drôle : dit à un inconnu, ça pèse moins."),H("Camille disait que les inconnus sont les meilleurs confidents. Ils n'ont pas de version de toi à protéger.")],x:"i14"},
i13e:{m:[H("D'accord. Vous avez le droit."),H("C'est dommage, j'avais préparé une deuxième vérité. Elle était bonne.")],x:"i14"},
x3c:{m:[H("Il m'a parlé de ce qu'elle aimait. Elle faisait des listes sur des tickets de métro. Des listes de choses à ne pas oublier."),H("« Appeler maman. Acheter du basilic. Dire à Inès que je l'aime. » Cette ligne-là, il dit qu'elle l'avait barrée trois fois. Puis réécrite.")],c:[["Elle a fini par te le dire ?","x3d",{t:2}],["Ça te fait quoi de l'entendre de lui, et pas d'elle ?","x3d",{t:1}]]},
x3d:{m:[H("Non. Pas en face. Elle ne me l'a jamais dit en face."),H("Je n'ai jamais lu les dernières pages du carnet. J'ai peur de ce qu'elle y dit. Il est resté quatorze mois sur mon étagère. Ce soir-là, je l'ai mis dans mon sac, comme un grand courage, et je l'ai perdu dans l'heure."),H("Tu crois que c'est un signe ?")],c:[["Je crois que c'est un hasard. Et que parfois, un hasard, ça suffit.","x4",{t:2}],["Je crois que tu l'as laissé sur ce banc pour que quelqu'un le trouve.","x4",{t:1}]]},
y3b:{m:[H("Tu crois qu'on peut répondre à une lettre qui n'attend plus de réponse ?")],c:[["On peut répondre quand même. C'est la phrase du carnet, non ?","y4",{t:2}],["Je crois qu'on répond à voix haute. Tu veux essayer ?","y4",{t:1}],["Je ne sais pas. Je n'ai perdu personne.","y4",{t:-1}]]},
q3b:{m:[H("Tu veux savoir le pire ?"),H("Il m'a quittée un jeudi, par texto. « On devrait se parler. » On ne s'est jamais parlé."),H("Huit mois après, il s'est mis avec Marion. Elle m'a prévenue avant tout le monde. Elle m'a demandé la permission."),H("J'ai dit oui. Parce que je disais oui à tout.")],c:[["Dire oui à tout, c'est une façon de ne rien dire.","q4",{t:2}],["Ça fait de Marion quelqu'un de bien.","q4",{t:1}]]},
q4b:{m:[N("Un deuxième message arrive, que Lou te transfère : « Où es-tu ?? On commence dans dix minutes. »"),H("C'est Marion. Elle a vu ma voiture par la fenêtre. Elle sait."),H("Elle ne me demande pas de venir. Elle me demande si j'ai mangé. Tu te rends compte ?")],c:[["C'est ça, une meilleure amie.","q4c",{t:1}],["Alors tu ne peux pas la laisser sans réponse.","q4c",{t:1}]]},
v3b:{m:[H("Adrien m'a demandé pardon. Pas pour Marion. Pour le texto du jeudi."),H("Il a dit : « Je ne savais pas comment te le dire. » Je lui ai répondu que ça faisait quatre ans de jeudis."),H("Je me suis sentie bizarrement grande.")],c:[["Tu l'es. Tu viens de monter quatre étages avec une colère sur le dos.","v4",{t:2}],["Tu as dit ce que tu pensais. C'est déjà énorme.","v4",{t:1}]]},
w1d:{m:[H("Parle-moi de toi. J'en ai marre de parler de moi.")],c:[["Je suis le genre de personne qui répond à un mauvais numéro. Je crois que ça résume l'essentiel.","w1e",{t:2}],["Je travaille beaucoup, je vois peu de monde. J'ai l'impression d'attendre quelque chose sans savoir quoi.","w1e",{t:2}],["Rien de très intéressant, honnêtement.","w1e",{t:-1}]]},
w1e:{m:[H("Je note : « répond aux inconnus, attend quelque chose. »"),H("Ça ressemble à la fiche d'un personnage de roman. Ou d'un chien fidèle. Je ne sais pas lequel je préfère.")],x:"w2"},
w3b:{m:[H("Je n'ai jamais voyagé seule. Je ne sais même pas où on s'assoit."),H("Couloir ou hublot ?")],c:[["Hublot. Comme ça, tu regardes dehors au lieu de regarder à l'intérieur.","w4b",{t:2}],["Couloir. Pour pouvoir fuir.","w4b",{t:1}]]},
p3x:{m:[H("Un truc que personne ne te dit : trois fois par jour, à 7h, 13h et 19h, tu lis le baromètre et tu envoies le bulletin à la capitainerie."),H("Si tu te trompes, un chalutier sort par force 9 en croyant à une accalmie. Premier bulletin dans une heure.")],c:[["Je n'ai jamais lu un baromètre de ma vie. Tu peux m'aider ?","p3y",{t:1}],["J'ai fait un stage de météo. Je devrais m'en sortir.","p3y",{t:0}]]},
p3y:{m:[N("12h58. Quatre-vingt-dix marches en colimaçon, et le baromètre, à droite de la lampe. Une étiquette collée dessus, écrite à la main : « 1008, ça va. 990, ça craint. »"),H("C'est moi qui l'ai écrit, il y a un an. Je pensais que je serais encore là pour lire les chiffres.")],c:[["Tu comptais rester longtemps ?","p3z",{t:1}],["1011. Je note.","p3q",{}]]},
p3z:{m:[H("Je pensais y rester jusqu'à la retraite. Dit comme ça, ça fait ridicule."),H("Mais il y a des endroits où on se sent à sa place avant même de savoir pourquoi.")],x:"p3q"},
k4c:{m:[N("Elle s'assoit sur une bitte d'amarrage. Longtemps."),N("« Mon frère disait que les gardiens de phare préfèrent les murs aux gens. Il se trompait sur Eliott. Il préférait les gens. Il ne savait juste pas comment les garder. »")],c:[["(à voix haute) Il m'a demandé de ne pas te laisser seule sur ce quai.","k5",{t:2},"!"],["(à voix haute) Je ne sais pas quoi te dire. Je reste là.","k5",{t:1},"!"]]},
o3b:{m:[H("Je veux que tu saches l'heure exacte. 23h47. J'ai noté sur le registre le feu rouge du bateau, puis plus rien."),H("Je me suis dit qu'ils avaient éteint pour économiser la batterie."),H("Le lendemain matin, au bulletin de 7h, un chalutier a signalé une coque retournée. Je suis remonté relire mon registre. J'avais écrit l'heure exacte où ils ont disparu.")],c:[["Tu as noté. Tu n'as pas fermé les yeux. C'est un début.","o3c",{t:2}],["Ça ne change rien pour Maëlle.","o3c",{t:0}]]},
q2b:{m:[H("Je porte la robe que Marion a choisie pour moi. Vert sauge. Elle m'a dit « ça t'ira bien ». Je ressemble à un buisson élégant."),H("Je me suis maquillée dans le rétroviseur. J'ai pleuré, j'ai refait. Deux fois.")],c:[["Tu as le droit d'être triste et très belle en vert sauge.","q3",{t:1}],["Un buisson élégant, ça a du charme. Les abeilles seront d'accord.","q3",{t:1}]]},
q4c:{m:[H("J'ai écrit un toast pour ce soir. Quatre phrases. Je les ai apprises par cœur et je les déteste."),H("Tu veux l'entendre ? Dis oui, sinon il va me pourrir dans la gorge.")],c:[["Dis-le. Je serai ton seul public, mais très attentif.","q4d",{t:2}],["Dis-moi plutôt ce que tu aurais aimé écrire.","q4e",{t:2}]]},
q4d:{m:[H("« Marion, tu es la personne la plus généreuse que je connaisse. Adrien, j'espère que tu le sais. »"),H("Voilà. Quatre phrases. Aucune n'est un mensonge. C'est ça qui est dur.")],x:"q5"},
q4e:{m:[H("Ce que j'aurais aimé écrire ?"),H("« Marion, merci de m'avoir demandé la permission. Adrien, j'ai fini de t'attendre. »"),H("Je ne sais pas si je pourrais le dire à voix haute.")],x:"q5"},
v2b:{m:[H("Plan : monter, dire bonjour, ne pas boire, partir dans dix minutes."),H("Je te donne un mot de passe. Si je t'écris « sauge », tu m'appelles pour me sauver.")],c:[["Sauge. Reçu. Je suis ton téléphone d'urgence.","v3",{t:2}],["Tu n'auras pas besoin de mot de passe. Tu peux partir quand tu veux.","v3",{t:1}]]},
w4b:{m:[H("J'ai écrit à Adrien cette nuit. Un seul message. Je l'ai relu dix fois."),H("« Je te pardonne. Pas pour toi. Pour pouvoir partir. »"),H("Je ne l'ai pas envoyé. Il est dans mes brouillons.")],c:[["Envoie-le, ou pas. Mais ne le garde pas comme une pierre dans la poche.","w4c",{t:2}],["Garde-le. Il est pour toi, pas pour lui.","w4c",{t:1}]]},
w4c:{m:[H("Je crois que je vais décider dans l'avion. Au-dessus des nuages, c'est plus facile d'avoir raison."),H("Je ne sais pas si c'est de l'humour ou de la panique.")],x:"w4"},
k1d:{m:[H("Elle descend toujours en dernier. Elle attend que tout le monde soit passé pour ne pas faire la queue."),H("Dis-moi quand tu la vois. Et n'écris rien d'autre. J'ai besoin de ce silence.")],c:[["Je te préviens dès que je la vois.","k2",{t:1}],["Tu as vraiment besoin que je sois ton œil ? Tu pourrais être ici.","k2",{t:0}]]},
o3c:{m:[N("Dans le grésillement de la radio, une voix : « Kerlo, ici le Gwenn-Ha, vous nous recevez ? Demande de bulletin. »"),N("C'est la première fois qu'on t'appelle par le nom du phare. Eliott t'écrit en même temps : « C'est eux. Les mêmes que ce soir-là. Réponds. »")],c:[["« Ici Kerlo. Vent de sud-ouest, force 7 forcissant 9, creux de trois mètres. Rentrez au port. »","o3d",{t:2}],["« Ici Kerlo… Je cherche mon papier, ne quittez pas. »","o3d",{t:0}]]},
o3d:{m:[N("« Reçu, Kerlo. On rentre. Merci, gamin. »"),H("Tu viens de faire ce que je n'ai pas fait. Je n'arrive pas à te dire ce que ça me fait.")],x:"o4"},
p2b:{m:[H("Il y a un calendrier derrière la porte de la cuisine ? Avec des croix ?")],c:[["Oui. Les croix s'arrêtent au 18 décembre.","p2c",{t:2}],["Je ne regarde pas. Je ne suis pas là pour fouiller.","p2d",{t:0}]]},
p2c:{m:[H("Le 18. Oui."),H("Après, j'ai arrêté de cocher. Je ne voulais plus savoir combien de jours il restait.")],x:"p3"},
p2d:{m:[H("Tu fais bien. Ce qui est écrit sur ces murs n'est pas à toi.")],x:"p3"},
p3q:{m:[H("Et toi ? Pourquoi un inconnu qui n'a jamais lu un baromètre accepte six mois sur un caillou ?")],c:[["Parce que j'avais besoin d'un endroit où personne ne me connaît.","p3r",{t:2}],["Parce que le salaire était bon et que je n'ai pas lu l'annonce jusqu'au bout.","p3r",{t:1}],["Je ne sais pas encore. Je te dirai quand je l'aurai trouvé.","p3r",{t:1}]]},
p3r:{m:[H("Ça, je comprends."),H("Les îles ont ce défaut. On y vient pour fuir, et on n'y trouve rien d'autre que soi.")],x:"p4"},
q1b:{m:[H("Une seconde. Avant de te raconter ma vie, ce qui est un peu indécent : tu fais quoi, un samedi à 14h12, pour répondre à une inconnue ?")],c:[["Je regardais la pluie sur mon balcon avec un café froid. Tu as sauvé mon samedi.","q2",{t:2}],["Je rangeais mon appartement. Un message d'inconnue, c'est plus intéressant que mes cartons.","q2",{t:1}]]},
p6b:{m:[N("19h00. Le bulletin du soir. Le baromètre est tombé à 994 en six heures."),H("994. Elle descend vite. Tu te rappelles l'étiquette ?"),H("Envoie le bulletin, puis ferme les volets côté mer. Et monte l'escalier en tenant la rampe, même si ça fait peur.")],c:[["Je le fais. Mais laisse-moi le numéro de la capitainerie, au cas où.","p7",{t:1}],["Tu n'as pas à me traiter comme un enfant.","p7",{t:0}]]},
});

Object.assign(S,{
l2_0:{w:"nuit",m:[N("18h26. La cérémonie est terminée. Ton téléphone vibre une dernière fois avant que tu ranges tes affaires."),H("C'est Lou. Je sais que c'est bizarre de réécrire au mauvais numéro, mais je voulais te dire ce qui s'est passé après."),H("Je suis entrée avec ma cousine. Je n'ai pas parlé à Adrien. J'ai surtout parlé à Marion, et ça m'a coûté beaucoup plus que je pensais.")],c:[["Tu n'as pas à me raconter la suite si tu préfères garder ça pour toi.","l2a",{bound:1,care:1}],["Qu'est-ce que tu as dit à Marion, exactement ?","l2b",{ask:1}],["Et tu m'écris parce que tu n'as personne d'autre à qui le dire ?","l2c",{honest:1}]]},
l2a:{m:[H("Merci. J'avais besoin de savoir que je pouvais raconter quelque chose sans devoir tout expliquer."),H("Marion m'a dit que mon silence l'avait blessée davantage que la vérité.")],c:[["C'est dur à entendre, mais au moins vous vous êtes parlé.","l3_0",{care:1}],["Tu crois que tu lui aurais dit sans cette conversation ?","l3_0",{ask:1}]]},
l2b:{m:[H("Je lui ai dit : 'Je suis heureuse pour toi, mais revoir Adrien m'a rappelé la vie que j'avais imaginée. Je ne te demande pas de réparer ça.'"),H("Elle aurait voulu le savoir plus tôt. Pas pour annuler le mariage, mais pour ne pas me laisser faire semblant toute seule. J'ai pleuré. Elle aussi, un peu.")],c:[["Tu as été honnête sans lui demander de choisir à ta place.","l3_0",{care:1,agency:1}],["Tu ne peux pas contrôler sa réaction, seulement la suite.","l3_0",{honest:1}]]},
l2c:{m:[H("J'ai ma cousine, mais je ne voulais pas qu'elle me voie encore comme 'celle qui va mal'."),H("Toi, tu étais censé être un numéro inconnu. C'est plus facile de parler à quelqu'un qui ne sait rien de moi."),H("Je voulais te remercier et vérifier que je ne t'avais pas mis mal à l'aise.")],c:[["Je préfère qu'on garde les choses à leur place.","l3_0",{bound:1}],["On peut se reparler, sans promesse.","l3_0",{care:1,t:1}]]},
l3_0:{w:"nuit",m:[N("20h03. Les notifications se sont arrêtées. Puis un nouveau message de Lou arrive."),H("Je viens de retrouver la photo de nos robes. Hier, je trouvais ça beau. Maintenant je ne sais plus si je veux la garder."),H("Je peux te demander un truc personnel ? Tu fais quoi, toi, quand tu as peur de décevoir quelqu'un ?")],c:[["Je fais parfois semblant que tout va bien. Ça évite une conversation, mais rarement le problème.","l3a",{honest:1}],["Je demande ce que la personne attend vraiment de moi, même si la réponse me fait peur.","l3b",{agency:1}],["Je ne te connais pas assez pour te raconter ma vie.","l3c",{bound:1}]]},
l3a:{m:[H("C'est exactement ce que j'ai fait aujourd'hui. Et après, j'en veux aux gens de ne pas avoir remarqué. C'est injuste, je le sais.")],x:"l4_0"},
l3b:{m:[H("J'aurais aimé avoir le courage de demander ça à Marion avant aujourd'hui. Je ne peux pas revenir en arrière, mais je peux arrêter de faire semblant.")],x:"l4_0"},
l3c:{m:[H("Tu as raison. Je t'ai écrit par erreur, tu ne me dois pas une intimité en échange. Je voulais te remercier, pas te demander de devenir mon confident.")],c:[["Bonne soirée, Lou. Prends soin de toi.","l4_0",{bound:1}],["On peut apprendre à se connaître doucement, si tu en as envie.","l4_0",{t:1,care:1}]]},
l4_0:{w:"nuit",m:[N("Le lendemain, 10h17."),H("Salut Sam. J'ai proposé un café à Marion la semaine prochaine. Elle a dit oui."),H("Elle m'a aussi dit qu'elle était blessée que je lui aie caché mes doutes. Je dois accepter les deux choses en même temps."),H("Je ne sais pas si on redeviendra comme avant. Mais au moins, on sait où on en est.")],c:[["Une relation peut changer sans disparaître. Laisse-lui le temps.","l4a",{care:1}],["Demande-lui aussi ce dont elle a besoin, pas seulement explique ce que tu ressens.","l4b",{practical:1}],["Qu'est-ce que tu veux maintenant, indépendamment de Marion et d'Adrien ?","l4c",{ask:1,agency:1}]]},
l4a:{m:[H("Je ne veux plus confondre 'différent' et 'fini'.")],x:"l5_0"},
l4b:{m:[H("Elle veut que je sois franche plus tôt, même quand je pense que ça va la décevoir. C'est raisonnable. Et difficile.")],x:"l5_0"},
l4c:{m:[H("Je veux chercher un poste à Nantes à nouveau. Celui que j'avais refusé n'existe plus, mais je peux arrêter de prétendre que je n'en ai jamais voulu. C'est la première décision de cette histoire qui ne tourne pas autour d'Adrien ou de Marion.")],x:"l5_0"},
l5_0:{m:[H("Je voulais te remercier une dernière fois. Tu n'as pas trouvé la phrase parfaite. Tu m'as surtout laissé choisir, et tu m'as dit quand tu ne savais pas."),H("Je vais supprimer ce fil, pas parce que je regrette de t'avoir écrit, mais parce que je veux retourner à ma vraie vie. Si on se recroise un jour, ce sera sans erreur de numéro."),N("Le téléphone s'éteint. Tu ne sauras pas tout ce qui arrive à Lou ensuite. Mais cette fois, le silence ne ressemble pas à une fuite.")],k:"Fin · Le mauvais numéro devient une vraie rencontre",e:["Fin · Le mauvais numéro devient une vraie rencontre","Lou a repris la responsabilité de ses choix, sans faire de l’inconnu son sauveur."]},
/* ===================== LE DERNIER EN LIGNE ===================== */
d1:{w:"champ",pro:["Le champ des Aulnes","Saint-Veyrac, 6h42. La brume coule entre les sillons. Le ruban de sécurité claque dans le vent froid.","Le laboureur qui a appelé attend près de son tracteur. Marcel Vautrin, 61 ans : « Je l'ai vu en passant. J'ai rien touché. »","Ta chef Élodie supervise la scène. Ton coéquipier Malik finit l'inventaire : « Léo Garnier, 32 ans, analyste informatique. Papiers, clés, portefeuille. »","Un détail te chiffonne : le corps a passé la nuit ailleurs, sur du béton. Quelqu'un a déplacé la géographie du crime.","Alors, près d'une touffe d'herbe, un téléphone se met à vibrer. Quatre appels manqués. Puis un message."],m:[Sy("4 appels manqués · numéro masqué"),H("Réponds. Je sais que tu as le téléphone. 🙂")],c:[["Signaler le téléphone. Scellés, procédure, zéro exception.","d1a",{int:4},"!"],["Le glisser dans ta poche. Personne n'a rien vu.","d1b",{int:1,tea:1},"!"],["Faire signe à Malik : « Mets-le de côté. On avisera. »","d1c",{int:2,tea:1},"!"]]},
d1a:{m:[N("Le téléphone part sous scellé. Chaîne impeccable. Élodie hoche la tête."),N("22h30, elle te rappelle : « Les proches bombardent son numéro. Si le meurtrier efface tout à distance, on perd le dossier cette nuit. »"),N("« Tu vas répondre à sa place. Chaque message au procès-verbal. C'est moche, mais c'est encadré. »")],x:"d2"},
d1b:{m:[N("Le téléphone disparaît dans ta poche. Une ligne d'inventaire saute. Elle pèsera plus lourd que tout le reste."),N("ÉLODIE : « Tu as trouvé autre chose ? »")],c:[["« Non. Rien d'ordinaire. »","d1b2",{tea:2}],["« Presque rien. Marcel a l'air d'en dire plus qu'il n'ose. »","d1b2",{tea:2,lie:1}]]},
d1b2:{w:"voiture",m:[N("Elle te fixe deux secondes de trop, puis hoche la tête. Pour cette fois."),N("Ce soir, dans ta voiture, tu ouvres le téléphone d'un mort. Tu vas devoir répondre à sa place.")],x:"d2"},
d1c:{m:[N("Malik baisse la voix : « Tu me demandes de sauter une ligne d'inventaire. Tu es sûr de ce que tu me demandes, Paul ? »")],c:[["« Oui. Et si ça te coûte, je le porte seul. »","d1c2",{malik:1,int:2}],["« Non, oublie. Je le prends moi-même. »","d1b",{int:1,tea:1}]]},
d1c2:{w:"voiture",m:[N("Il exhale : « Écart provisoire. Et le jour où ça retombe, tu ne me fais pas tomber avec. »"),N("Ce soir, il te tend le téléphone dans le parking.")],x:"d2"},
d2:{w:"voiture",app:"WhatsApp",nm:"Les Inoubliables",stx:"Camille · Jeanne",mem:["Camille","Jeanne"],prev:"Camille : Léo, réponds…",m:[Sy("Les Inoubliables — le groupe de Léo · Camille, sa compagne · Jeanne, sa sœur"),H("Camille : Léo. Tu m'avais promis d'arrêter avec cette histoire. Réponds."),H("Jeanne : Si tu as trouvé ce que papa avait laissé, ne fais rien avant de me parler."),N("22h14. Pluie sur le pare-brise. Sur l'écran d'accueil, un dossier verrouillé : ORPHÉE.")],c:[["Répondre à Camille.","d2c",{cam:1},"!"],["Appeler Jeanne.","d2j",{jea:1},"!"],["Ne répondre à personne ce soir.","d2s",{sad:1},"!"]]},
d2c:{app:"WhatsApp",nm:"Camille",stx:"en ligne",mem:["Camille"],m:[N("Tu tapes avec les mots de Léo : « Je suis en sécurité. Je t'explique plus tard. »"),H("Si c'est encore à cause de lui… appelle-moi. Pas un message. Un appel.")],c:[["« Promis. Dors, Camille. »","d2c2",{cam:2}],["« Laisse tomber les grands discours. Ça va. »","d2c3",{cam:1,sad:1}]]},
d2c2:{m:[H("Et si tu veux un nom, puisque tu ne veux rien me dire : Adrien Valette. Responsable chez Vigilex Sécurité."),N("Le genre d'homme qui fait disparaître des dossiers. Et parfois des gens. Premier nom sur le tableau.")],x:"d3"},
d2c3:{m:[H("…Bon. D'accord. Mais tu ne me fais pas confiance, c'est ça ?"),N("Le silence qui suit coûte plus cher que la réponse. Tu ne sauras rien de plus ce soir, sinon ce prénom lâché en partant : un certain Adrien, chez Vigilex.")],x:"d3"},
d2j:{app:"WhatsApp",nm:"Jeanne",stx:"en ligne",mem:["Jeanne"],call:["Jeanne","Appel WhatsApp · 22h31",[[1,"Allô ? Léo ? Enfin. Trois jours sans un mot, et tu rappelles à 22h31 ?"],[0,"Tu ne dis rien. C'est la sœur de Léo — tu ne peux pas lui parler avec la voix de son frère."],[1,"…Je t'entends respirer. Ce n'est pas drôle, Léo. Tu m'avais promis d'arrêter de disparaître."],[0,"Le silence s'étire. Tu serres le téléphone, incapable du moindre mot."],[1,"Ce n'est pas Léo. Léo m'aurait parlé de papa dans les trois premières secondes. Qui êtes-vous ?"],[0,"Elle attend. Deux secondes. Dix."],[1,"Il est arrivé quelque chose à Léo, c'est ça ? Dites-le-moi. S'il vous plaît."],[0,"Tu ne réponds toujours pas. Un dernier souffle à l'autre bout — puis le bip libre : elle a raccroché la première."]]],m:[N("Le fil mort à la main, tu restes immobile dans la voiture. Quelques secondes plus tard, le téléphone vibre."),H("Je ne sais pas qui vous êtes. Mais si vous avez ce téléphone, c'est que vous cherchez ce qui lui est arrivé. Alors écoutez-moi bien.")],c:[["« Je suis enquêteur. Je ne peux rien dire de plus ce soir. »","d2j2",{jea:2}],["« Je suis désolé pour l'appel. Je ne pouvais pas parler. Aidez-moi à comprendre. »","d2j3",{jea:1}]]},
d2j2:{m:[H("Un enquêteur. Enfin quelqu'un qui le cherche."),H("Alors notez bien : papa n'est pas mort parce qu'il a perdu le contrôle de sa voiture. Et si Léo a retrouvé le coffre, ne le faites pas seul. Je vous aiderai.")],x:"d3"},
d2j3:{m:[H("Papa réparait des choses que personne ne voulait entendre. Sa voiture a quitté la route un soir de gel. Maman n'y a jamais cru. Léo non plus."),H("C'est tout ce que je peux vous donner ce soir. Ne me rappelez pas — j'écrirai.")],x:"d3"},
d2s:{w:"voiture",m:[N("Tu poses le téléphone face contre le siège. Les messages s'accumulent. Puis un numéro inconnu : +33 6 84 •• •• 17."),H("Tu comptes les gens à qui tu ne réponds pas ? Moi aussi.")],x:"d3"},
d3:{w:"voiture",app:"SMS",nm:"Numéro masqué",prev:"Numéro masqué : Tu n'es pas Léo.",m:[N("23h02. Une notification. Pas le groupe. Le numéro inconnu."),H("Tu n'es pas Léo. Un frère ne laisse pas sa sœur sans nouvelles trois jours, puis répond au bout de la nuit. Dis-moi qui tu es. 🙂")],c:[["« Je ne dois rien à un numéro masqué. Cessez, ou ce fil remonte au service qui traite les menaces. »","d3a",{sad:1}],["« Léo m'a prêté son téléphone. Il est hors réseau quelques jours. »","d3b",{sad:2,lie:1}],["Bloquer le numéro.","d3c",{sad:1,bloq:1},"!"],["« Vous avez mon nom en dix secondes si vous êtes clean. Qui es-tu, toi ? »","d3d",{sad:2}]]},
d3a:{w:"voiture",m:[H("Remonter à qui ? Vous croyez que ça s'arrête au premier étage d'un commissariat ?"),H("Calmez-vous, « Léo ». Je ne vais rien faire. Je constate. C'est tout ce que je fais : constater."),N("Il te teste. Il ne sait pas qui tu es — mais il sait ce que tu n'es pas.")],x:"d4"},
d3b:{w:"voiture",m:[H("Hors réseau. Quelques jours. Bien sûr."),H("Ses affaires à lui sont restées à la maison, alors ? Vous mentez avec les mots d'un homme qui n'aurait jamais laissé ce téléphone à personne. C'est mal connaître Léo — et moi."),N("Chaque mensonge peut être vérifié. Il a l'œil sur quelque chose — ou sur quelqu'un.")],x:"d4"},
d3c:{w:"voiture",m:[N("Numéro bloqué. Vingt minutes plus tard, un e-mail sur le téléphone de Léo, pièce jointe : une photo du commissariat, prise ce soir depuis la route."),N("Il n'a même pas essayé de rappeler. Il change de canal comme tu changes de porte — ce jeu ne fait que commencer.")],x:"d4"},
d3d:{w:"voiture",m:[H("Moi ? Je décide de ce qui reste en ligne et de ce qui disparaît. Des dossiers. Des gens. Des conversations, comme celle-ci."),H("Vous, par exemple : vous n'existez nulle part dans la vie de Léo. C'est le premier vrai truc que je sais de vous."),N("Il surveille les proches de Léo. Et maintenant, toi.")],x:"d4"},
d4:{w:"voiture",app:"WhatsApp",nm:"Projet Orphée",stx:"Archivé · lecture seule",mem:["Léo","Adrien","V."],prev:"V. : Cette conversation n'a jamais existé.",m:[Sy("Tu ouvres les archives WhatsApp du téléphone de Léo. Un groupe qu'il avait enterré tout en bas : « Projet Orphée ». Trois membres : Léo, Adrien Valette — et « V. », le +33 6 84 •• •• 17 qui t'a écrit ce soir."),N("La conversation s'affiche. Les derniers messages, datés de la veille de la disparition :"),H("Léo : Les sauvegardes ne disparaissent pas toutes seules. J'ai les journaux d'accès. J'ai fait des copies."),H("Adrien : Alors tu viens de mettre des gens en danger."),H("V. : Cette conversation n'a jamais existé."),N("Dessous : des pièces jointes, et un dossier épinglé, verrouillé. Le dossier ORPHÉE de l'écran d'accueil.")],c:[["Ouvrir les journaux d'accès.","d4a",{pov:2},"!"],["Ouvrir le brouillon de Léo.","d4b",{prm:1},"!"],["Exporter ce qui n'est pas chiffré, puis refermer.","d4c",{rec:1},"!"]]},
d4a:{w:"voiture",app:"Fichiers",nm:"journal_acces.log",stx:"Pièce jointe · ouverte",m:[Sy("journal_acces.log — 2,4 Mo · pièce jointe de Léo dans « Projet Orphée »"),N("Le fichier s'ouvre. Trois ans de requêtes de géolocalisation hors procédure. Des dates qui entourent la mort du père de Léo, dix ans plus tôt."),N("Un identifiant revient plus que les autres : AV-7734."),N("La dernière requête date d'hier, 23h47 — après la mort de Léo. Quelqu'un d'autre utilise encore ce compte.")],c:[["Ouvrir le brouillon de Léo.","d4b",{prm:1},"!"],["Refermer. Assez vu pour ce soir.","d5",{},"!"]]},
d4b:{w:"voiture",app:"Fichiers",nm:"brouillon_leo.m4a",stx:"Pièce jointe · ouverte",m:[Sy("brouillon_leo.m4a — 1:42 · un message vocal pour Camille, resté en brouillon"),N("Tu appuies sur lecture. La voix de Léo emplit la voiture :"),H("Si je ne reviens pas, ne crois pas celui qui te dira qu'il voulait seulement me faire peur."),N("Dessous, une fiche d'un ancien technicien de Vigilex — parti « en burn-out » deux ans plus tôt, introuvable depuis. C'est lui qui générait ces journaux d'accès : celui qui a aidé Léo à voir. Et qui a disparu juste après."),N("Deux hommes qui savaient. Un mort, un disparu. Et un dossier épinglé qu'il reste à ouvrir.")],c:[["Ouvrir les journaux d'accès.","d4a",{pov:2},"!"],["Exporter, puis refermer.","d4c",{rec:1},"!"]]},
d4c:{w:"voiture",m:[N("Tu exportes ce qui peut l'être — depuis un dossier que tu n'aurais jamais dû ouvrir hors scellés."),H("Tu es encore réveillé, « Léo » ? Les gens qui dorment bien ne consultent pas les archives à minuit.")],x:"d5"},
d5:{w:"cafe",app:"SMS",nm:"Numéro inconnu",m:[Sy("Ce n'est pas le numéro masqué d'hier. Un autre inconnu — mais celui-là écrit comme quelqu'un qui a peur."),N("Le lendemain, 12h40. La pluie s'est levée pour la journée."),H("Je sais que tu me mens. Si tu es vraiment Léo, dis-moi ce que tu m'as dit le soir où on s'est séparés.")],c:[["« Tu m'as dit que j'étais difficile à suivre, mais que tu ne regrettais rien. »","d5a",{cam:1}],["« Je ne suis pas Léo. Et j'ai besoin de te parler. »","d5b",{cam:1}],["« Léo est parti respirer. Il t'écrira. »","d5c",{lie:1,cam:1}],["Proposer un café, dans une heure.","d5d",{cam:2}]]},
d5a:{w:"cafe",m:[H("…C'est presque ça. Presque. Mais tu n'as pas repris la fin — et la fin, c'est la seule chose dont je me souvenais."),N("Une heure de silence, puis une seule question sur Adrien, sèche. Elle a compris qu'on lui récite un texte."),N("Tu renommes le numéro dans le téléphone de Léo : Camille.")],x:"d6"},
d5b:{w:"cafe",m:[N("Trois points, longuement. Puis :"),H("Il est mort, n'est-ce pas ?"),N("Tu confirmes. Elle pleure sans faire de bruit : « Qui êtes-vous ? » — « Quelqu'un qui essaie de comprendre. »"),N("« Alors venez me parler. » Elle t'envoie l'adresse d'un café, dans une heure.")],x:"d5d"},
d5c:{w:"cafe",m:[H("Parti. Sans rien dire. Comme toujours. Il finira par revenir, il finira toujours par revenir."),H("S'il ne revient pas, sachez qu'il cachait des copies chez son avocate. Maître Lemaire. Rue des Carmes."),N("Elle livre quand même cette info, pour conjurer le mauvais sort. Tu renommes le numéro dans le téléphone de Léo : Camille.")],x:"d6"},
d5d:{w:"cafe",m:[N("Le café des Halles, 14h. Camille ne boit rien. Elle regarde tes mains : « Les mains de quelqu'un qui n'a pas l'habitude de mentir pour vivre. »"),N("Elle fait glisser une photo : Michel Garnier devant un bâtiment de télécoms. Au dos, l'écriture de Léo : « Incident Orphée — ne pas oublier. »"),N("Ton téléphone à toi vibre. Numéro masqué : « Je sais que tu es au café. Tu n'es pas aussi discret que tu le crois. »"),N("Tu renommes le numéro de l'inconnue dans le téléphone de Léo : Camille.")],c:[["« Je fais ça pour Léo. Aide-moi à finir ce qu'il a commencé. »","d5d2",{cam:3}],["« Oublie ce que tu as vu. Laisse-moi gérer. »","d5d3",{cam:1}]]},
d5d2:{w:"cafe",m:[N("Elle hoche la tête : « Il avait mis des copies chez son avocate, Maître Lemaire. S'il t'arrive quelque chose, elle saura quoi en faire. »"),N("En sortant, elle te prend le bras : « Faites attention. Il a l'habitude des gens qui disparaissent. »")],x:"d6"},
d5d3:{w:"cafe",m:[N("Elle repousse la photo : « Quelqu'un d'autre qui sait mieux que tout le monde. » Elle part sans payer."),N("Le numéro masqué renchérit : « Première leçon : les témoins, ça se protège. »")],x:"d6"},
d6:{w:"bureau",m:[N("16h50. Élodie fait tourner les radiographies : « Le corps a passé des heures sur du béton, avant le champ. Et le décès, entre 22h et minuit, contredit un certain Valette — il prétend avoir quitté Léo serein à 23h30. »"),N("« Il ment, ou il s'est trompé. Dans les deux cas, il faut creuser. »")],c:[["Aller revoir Marcel, à la ferme.","d6a",{prm:1},"!"],["Rentrer au poste. Trier ce que tu as.","d6b",{},"!"]]},
d6a:{w:"grange",m:[N("MARCEL : « Une voiture près de la grange, cette nuit-là, vers trois heures. Je n'ai rien dit — j'ai des subventions pas très propres dans mes placards. »"),N("« La plaque ? Pas entière. Mais le feu arrière gauche était cassé. »"),N("Le lendemain, dans les photos Vigilex : un utilitaire gris, feu arrière gauche brisé. Sorti du parc le soir du meurtre, « maintenance », signé A. Valette.")],c:[["Photographier la fiche et le véhicule.","d6a2",{prm:2},"!"],["Noter de mémoire. Trop de copies, c'est suspect.","d6a3",{prm:1},"!"]]},
d6a2:{w:"grange",m:[N("La photo rejoint le dossier. Elle vaudra ce qu'elle vaudra — mais elle existe.")],x:"d7"},
d6a3:{w:"grange",m:[N("Dates, heures, plaque partielle, feu cassé. Dans ta tête, et nulle part ailleurs.")],x:"d7"},
d6b:{w:"bureau",m:[N("Tu ranges les radiographies. Au dossier, tout se corrobore ou se dément — pas dans les couloirs.")],x:"d7"},
d7:{w:"bureau",m:[N("20h15, le bureau. Malik pose le relevé des effets devant toi : « Il manque une ligne entre les clés et le portefeuille. »"),N("« Une erreur de saisie. Je corrige. » — « Une erreur, ça arrive. Deux, ça devient une histoire. »")],c:[["Tout dire à Élodie maintenant.","d7a",{aveu:1,int:4},"!"],["« Le registre a pris l'eau sur le terrain. »","d7b",{lie:1,tea:2}],["Demander à Malik de classer ça en écart provisoire.","d7c",{},"!"]]},
d7a:{w:"bureau",m:[N("Tu poses le téléphone de Léo sur le bureau d'Élodie, écran allumé. Tu racontes tout : l'herbe, la poche, la ligne sautée, les réponses."),N("ÉLODIE : « On régularise. Scellés tardifs, procès-verbal, inspection de tes derniers mois. Tu le paieras. Mais le dossier survivra. »")],x:"d8"},
d7b:{w:"bureau",m:[N("MALIK : « Le registre a pris l'eau. Sur ce point. Précisément. »"),N("Il ne dit rien de plus. Tu le vois sortir son carnet en quittant la salle de pause.")],x:"d8"},
d7c:{w:"bureau",m:[N("Malik replie sa serviette : « Je suis déjà dedans jusqu'au coude. Je peux te couvrir une semaine. Une seule. Après, je déclare l'anomalie moi-même. »")],c:[["« Merci. Une semaine me suffit. »","d7c2",{malik:1}],["« Non. Je vais dire la vérité à Élodie. »","d7a",{aveu:1,int:4}]]},
d7c2:{w:"bureau",m:[N("L'inventaire respire. Malik recule d'un demi-pas, sans vraiment lâcher l'affaire.")],x:"d8"},
d8:{w:"ormes",pro:["Le centre des Ormes","Deux jours plus tard. Les journaux de Léo pointent tous vers le même lieu : l'ancien centre de télécoms du plateau. Le centre des Ormes. Une ombre carrée dans la pluie.","À l'intérieur : un disque dur étiqueté à la main, des dates qui entourent la mort de Michel Garnier. Un carnet de contrats. Des photos de visages surveillés.","Punaisée au mur, une phrase : « Michel n'est pas mort parce qu'il a perdu le contrôle de sa voiture. »","Un bruit de pas sur le gravier. Une voix calme, derrière toi."],m:[N("ADRIEN : « Tu aurais dû laisser ce téléphone où il était. »")],c:[["« Tu as tué Léo. »","d8t",{}],["« Comment tu m'as trouvé ? »","d8t",{}]]},
d8t:{w:"ormes",m:[N("ADRIEN : « Léo a cru qu'il pouvait détruire des vies avec des fichiers. Je l'ai empêché de faire quelque chose d'irréversible. C'est la version que tu peux prouver ? »"),N("Il fait tourner une clé USB entre ses doigts, comme une pièce.")],x:"d8t2"},
d8t2:{w:"ormes",tel:["6h47","Ton téléphone","+33 6 84 •• •• 17","Puisque nous discutons franchement, commandant : ce message arrive bien sur le tien. Celui de Léo ne t'a jamais servi à te cacher."],m:[N("Dans ta poche, ton propre téléphone vibre. Même numéro que sur celui de Léo. Il sourit : « Ici : les données de Léo, un mot de passe, un dossier classé sans suite. En échange, tu oublies Orphée. Personne n'en entendra jamais parler. »"),Sy("📝 Astuce : tes notes sont à jour avant ce choix.")],c:[["Refuser et tenter de le retenir ici.","d8r",{},"!"],["Accepter en apparence, pour gagner du temps.","d8f",{feinte:1},"!"],["Accepter. Détruire les copies.","d8k",{accord:1},"!"],["Reculer et appeler Malik, maintenant.","d8p",{malik:1},"!"],["Venir de face, seul, et le provoquer.","d8s",{},"!"]]},
d8r:{w:"ormes",m:[N("Le contacteur claque — noir total. Une douleur sèche dans les côtes, le béton."),N("Quand des phares balaient le hall, tu es seul, le nez en sang, une côte fêlée. Dehors, des pas crissent sur le gravier. En marchant. Sans courir.")],c:[["Noter ce que tu as vu et appeler les secours.","d8z",{bless:1},"!"]]},
d8f:{w:"ormes",m:[N("Tu prends la clé USB sans un mot. Dans la voiture, tu ne branches rien : tu la photographies, tu notes le contrat imprimé sur l'étiquette."),N("Gagner du temps, c'est déjà le faire mentir.")],x:"d8z"},
d8k:{w:"ormes",m:[N("Tu tends les copies. Il les brûle dans un bidon, méthodique. « Une nouvelle vie de tranquillité commence demain. »"),N("Sur le chemin du retour, tu ne t'es jamais senti aussi sale.")],x:"d8z"},
d8p:{w:"ormes",m:[N("Tu recules, main levée, et tu appelles Malik en marchant vers la sortie : « Centre des Ormes. Il est ici. »"),N("Adrien sourit : « Tu invites du monde à ta propre descente ? » — et il sort, très calme, sous la pluie.")],x:"d8z"},
d8s:{w:"ormes",m:[N("Tu fonces. Noir. Un coup de traverse, le souffle coupé. Il te regarde du haut de la passerelle, comme un incident de gestion : « La prochaine fois, je ne te laisserai pas repartir. »")],c:[["Ramper vers la sortie et survivre.","d8z",{bless:2,sad:2},"!"],["Te relever et tenir tête.","d8z2",{bless:2},"!"]]},
d8z2:{w:"ormes",m:[N("Tu tiens debout, à peine. Il te regarde longuement, puis secoue la tête : « Tu n'es même plus une anomalie. Tu es un incident. »"),N("Il te laisse vivant, par indifférence plus que par pitié.")],x:"d8z"},
d8z:{j:s=>s.bloq?"d8zb":"d8za"},
d8za:{w:"ormes",m:[N("Cette nuit-là, le téléphone de Léo clignote longtemps. Sur « Les Inoubliables », le fil s'enflamme : Camille partage un appel à témoins, Jeanne la supplie de ne rien publier seule."),H("Quelqu'un est venu chez moi. Je crois que c'était pour toi. — Camille"),H("J'ai trouvé une anomalie dans un ancien dossier, celui de 2016. Appelle-moi. — Malik"),H("La prochaine fois, je ne te laisserai pas repartir.")],x:"d9"},
d8zb:{w:"ormes",m:[N("Cette nuit-là, le téléphone de Léo clignote longtemps. Sur « Les Inoubliables », le fil s'enflamme : Camille partage un appel à témoins, Jeanne la supplie de ne rien publier seule."),H("Quelqu'un est venu chez moi. Je crois que c'était pour toi. — Camille"),H("J'ai trouvé une anomalie dans un ancien dossier, celui de 2016. Appelle-moi. — Malik"),H("Tu m'as bloqué ? On ne bloque pas celui qui écrit depuis vos propres comptes.")],x:"d9"},
d9:{w:"archives",m:[N("Le dossier « Garnier, M. » de 2016 dort au sous-sol. Le rapport minimise tout : « anomalies ponctuelles, absence de faisceau. » Enterré par un haut gradé, jamais nommé."),N("Léo avait annoté la copie de son père : les journaux d'accès, les flux financiers, et un enregistrement où Valette évoque l'accident de Michel comme une affaire « à régler ».")],c:[["Retrouver le coffre de dépôt de Michel.","d9a",{},"!"],["Prévenir la presse. Camille connaît une journaliste.","d9b",{pov:1},"!"],["Tout mettre au propre : copies, dates, procès-verbaux.","d9c",{rec:1},"!"]]},
d9a:{w:"archives",j:s=>s.jea?"d9a2":"d9a1"},
d9a1:{w:"archives",m:[N("Le coffre existe — mais sa référence, c'est Jeanne qui l'a. Sans elle, la banque ne t'ouvrira rien.")],c:[["Appeler Jeanne maintenant. Sans elle, l'enquête s'arrête là.","d9j",{jea:1},"!"],["Trop tard pour les retrouvements. Garder ça pour un autre jour.","d10z",{},"!"]]},
d9j:{app:"WhatsApp",nm:"Jeanne",stx:"en ligne",mem:["Jeanne"],call:["Jeanne","Appel WhatsApp · 21h07",[[1,"Allô ? …Tu appelles pour papa ?"],[0,"Tu lui expliques, sans tout dire. Un long silence à l'autre bout du fil."],[1,"Alors note bien. Il l'avait préparée pour moi, cette référence. Tu es prêt ?"],[0,"Elle te la dicte, chiffre par chiffre, comme on transmet un secret de famille."],[1,"Il avait tout prévu. Même ce moment-là. Prends soin de toi, quoi qu'il arrive."]]],m:[N("Elle raccroche. La référence du coffre est notée noir sur blanc.")],x:"d9a2"},
d9a2:{m:[N("Jeanne t'envoie la référence que Léo avait préparée pour elle. Dans la petite salle capitonnée, tu ouvres la boîte : une clé USB, une lettre de Michel, un numéro de contrat."),N("MICHEL : « Prouve ce que j'ai vu. Ne les laisse pas transformer mes erreurs en raison de m'ignorer. »")],c:[["Photographier chaque page du coffre.","d10z",{pov:2,prm:1},"!"],["Refermer, et tout mémoriser.","d10z",{pov:1,prm:1},"!"]]},
d9b:{w:"archives",m:[N("Camille te met en contact avec une journaliste. Elle veut des preuves vérifiées, corroborées indépendamment — elle a déjà vu des enquêtes mourir d'une publication prématurée."),N("Elle attend. Mais ses sources confirment déjà : les sociétés intermédiaires, les marchés doublés, tout converge.")],x:"d10z"},
d9c:{w:"archives",m:[N("Tu passes la nuit à tout mettre au propre : copies horodatées, procès-verbaux, dates, noms. Ce qui n'existe pas proprement n'existe pas du tout.")],x:"d10z"},
d10z:{app:"WhatsApp",nm:"Jeanne",stx:"en ligne",mem:["Jeanne"],m:[N("04 h 12. Le café d'à côté a fermé depuis deux heures ; il ne reste que la lumière blanche du couloir de la banque, puis l'écran du téléphone. Jeanne est en ligne. Elle aussi, apparemment, n'a pas dormi."),H("Toujours debout ? Papa ne dormait jamais non plus, les dernières nuits. Il disait que c'était là que tout se décidait.")],c:[["Tout lui dire. Le coffre, ORPHÉE, ce que tu risques vraiment.","d10",{jea:1,int:1},"Le coffre de ton père est ouvert. Il y a tout : l'accident, les marchés, les noms. Je suis sur le point de faire quelque chose d'irréversible."],["La protéger. Un mensonge doux, pour qu'elle dorme deux heures de plus.","d10",{lie:1},"Presque fini. Dors, Jeanne."],["Ne pas répondre. Éteindre l'écran. Personne ne doit savoir où tu es à cette heure.","d10",{bloq:1},"!"]]},
d10:{m:[N("48 heures plus tard. Tout ce que tu as tient dans une poche de veste : un téléphone volé, des copies fragiles, des noms. Reste à choisir comment ça se termine."),Sy("📝 Tes notes sont à jour — jette un œil via le bouton Apps avant de choisir.")],c:[["La voie officielle : tout avouer à Élodie.","d11a",{aveu:1,int:4},"!"],["Le rendez-vous clandestin : faire croire à Adrien que tu as les originaux.","d10b",{},"!"],["La publication : donner tout à la presse.","d11c",{pub:1,pov:1},"!"],["L'accord avec Adrien : détruire, signer, survivre.","d11d",{accord:1},"!"],["Accuser Marcel : orienter le dossier vers le meilleur coupable disponible.","d11e",{lie:1},"!"]]},
d10b:{m:[N("Reste une question : du renfort, ou personne ?")],c:[["Appeler Malik. Il est déjà dedans jusqu'au coude.","d11b",{rdv:1,malik:1},"!"],["Aucun renfort. Ce risque est à toi seul.","d11b",{rdv:1},"!"]]},
d11a:{m:[N("Salle d'Élodie, 8h. Tu poses le téléphone, les copies, le procès-verbal de tes fautes. Elle écoute jusqu'au bout : « On sécurise, on corrobore, on frappe légalement. Et toi, tu restes à l'écriture du dossier. »"),N("L'opération est montée en douze heures. Interpellation chez Vigilex, perquisitions, le disque dur des Ormes sous scellé.")],j:s=>s.pov>=2&&s.prm>=2?(s.int>=3&&s.aveu?"dG":"dA"):s.pov>=2?"dH":"dD"},
d11b:{m:[N("23h40, centre des Ormes. Les copies « originales » sur la table, à la lampe de chantier qu'il a lui-même branchée."),N("ADRIEN : « Tu as fait tout ça pour un téléphone volé ? » — PAUL : « Non. Pour tout ce que personne ne regardait derrière tes contrats. »"),N("« Si tu me fais tomber, tu tombes avec moi. » — « Peut-être. Mais je n'efface pas ce que tu as fait. »")],j:s=>s.malik?"d11bm":"d11bs"},
d11bm:{m:[N("Le courant saute au signal. La lampe frontale de Malik balaie le hall — il est là parce que tu l'as appelé, et lui seul. La lutte est courte. Adrien tombe, menotté.")],j:s=>s.pov>=2&&s.prm>=2&&s.int>=2?(s.aveu&&s.int>=3?"dG":"dA"):"dB"},
d11bs:{m:[N("Le contacteur claque — noir total. Sa respiration est quelque part à gauche. La tienne aussi.")],c:[["Foncer sur lui dans le noir.","d11bt",{},"!"],["Reculer vers la sortie en criant que les renforts arrivent.","d11br",{bless:1},"!"]]},
d11bt:{m:[N("Il te voit venir avant que tes yeux s'habituent. Une douleur exacte, puis le béton froid : personne ne viendra, tu n'as prévenu personne."),N("Les pas s'éloignent vers le gravier. En marchant. Comme toujours.")],x:"dE"},
d11br:{m:[N("Tu recules en hurlant que les renforts arrivent. Mensonge. Il hésite une seconde — une seule — puis part : les gens comme lui ne jouent pas aux dés avec les mensonges des autres."),N("Tu restes seul dans le noir, vivant, sans rien.")],j:s=>s.pov>=2?"dH":"dD"},
d11c:{m:[N("La journaliste publie un jeudi matin : « ORPHÉE, la surveillance invisible. » Contrats, sociétés intermédiaires, journaux d'accès — vérifié deux fois.")],j:s=>s.pov>=2?"dC":"dD"},
d11d:{m:[N("Tu remets ce qui reste, tu signes, tu détruis. Adrien te laisse même une lettre de recommandation : « Le monde tient debout grâce aux gens raisonnables. »")],x:"dF"},
d11e:{m:[N("Le dossier s'oriente vers Marcel : ses subventions, ses horaires, « sa » découverte du corps. Garde à vue, seize heures — puis tout s'effondre : aucun lien, aucune trace, aucun mobile.")],x:"dD"},
dA:{m:[N("Trois semaines plus tard. Les journaux, le véhicule au feu cassé, l'alibi qui s'effondre : Adrien Valette est mis en examen pour le meurtre de Léo et pour ORPHÉE. L'affaire Michel est rouverte."),N("Et toi, tu es entendu pour soustraction de pièce à conviction. Tu ne sors pas indemne — les preuves, elles, sortent intactes."),N("Tu rends ton badge avant d'entrer dans la salle d'audition. Derrière toi, une dernière notification :"),H("Léo aurait voulu que ça sorte. Merci. — Jeanne"),N("Plus tard, tu écoutes enfin le fichier « Si je ne reviens pas » : « J'avais peur. J'ai fini par comprendre que si je me taisais, quelqu'un d'autre aurait peur à ma place. »")],k:"Fin · La vérité au prix de la carrière"},
dB:{w:"ormes",m:[N("Le courant revient. Malik est là, arme au poing — c'est toi qui l'as appelé, et lui qui a couru. Adrien tombe, menotté."),N("Mais devant la défense, le dossier s'effrite : sans scellés, sans chaîne de conservation, certaines pièces sont fragiles. Tu quittes le terrain, enquête disciplinaire en cours."),N("En sortant, Adrien passe devant toi, encadré par deux gendarmes."),H("Tu as gagné une bataille.")],k:"Fin · Le coupable, mais un dossier fragile"},
dC:{m:[N("Le scandale déborde sur les réseaux, puis les chaînes nationales. Adrien tente de fuir — les autorités le rattrapent grâce aux éléments matériels. Mais d'autres pièces disparaissent : la publication a alerté plus de gens que prévu. Tu réponds de tes méthodes."),N("Au café, les gros titres défilent au-dessus du comptoir. Puis, sur le téléphone de la journaliste, un fichier anonyme :"),H("ORPHÉE — NIVEAU 2"),N("Elle le garde. Pour la prochaine histoire — qui n'aura pas besoin de toi pour commencer.")],k:"Fin · La vérité publique"},
dD:{m:[N("Pendant ce temps, Adrien nettoie : les données s'évaporent, les témoins se rétractent. Une fuite judiciaire pointe vers toi : c'est l'enquêteur qui a soustrait le téléphone. Suspension, classement « auteur non identifié »."),N("Un soir, sur un téléphone saisi :"),H("Tu aurais dû rester dans ton champ."),N("Le compte, déjà supprimé, n'a jamais existé. Comme cette conversation. Comme le reste.")],k:"Fin · Le bouc émissaire"},
dE:{w:"ormes",m:[N("Le courant claque une dernière fois. Tu ne verras plus rien du tout. Adrien essuie la clé USB sur sa manche et repart sous la pluie, en marchant. On te retrouvera au petit matin, sur le seuil des Ormes."),N("Le téléphone de Léo exécute sa dernière consigne : un message programmé part pour Jeanne."),H("Tout est réglé. Ne cherchez plus."),Sy("Hors ligne")],k:"Fin · Le dernier message"},
dF:{w:"bureau",m:[N("Le dossier est classé : meurtre sans auteur identifié. Ta carrière semble sauvée — un dossier propre, une prime de fin d'année. Adrien tient sa part du marché. Pour l'instant. Toi aussi."),N("Tu as sacrifié Léo une deuxième fois. La première, c'était un meurtrier. La deuxième, c'était toi. Quelques jours plus tard :"),H("Vous avez fait le bon choix. Pour l'instant.")],k:"Fin · L'accord du silence"},
dG:{w:"bureau",m:[N("Tu remets tout : téléphone, copies, fautes, noms. Élodie organise une confrontation légale, enregistrée — et Adrien n'a plus de pièce à faire tourner entre ses doigts. Le meurtre de Léo est établi : le mobile, les journaux, le véhicule, l'alibi. ORPHÉE tombe avec lui."),N("Tu attends la décision disciplinaire sur une chaise en plastique, dans un couloir. Tu n'es peut-être plus enquêteur du tout — mais l'affaire ne disparaîtra pas."),N("Avant de rendre le téléphone, tu écoutes « Si je ne reviens pas » jusqu'au bout : « J'avais peur. J'ai fini par comprendre que si je me taisais, quelqu'un d'autre aurait peur à ma place. »")],k:"Fin · Le sacrifice"},
dH:{m:[N("ORPHÉE est prouvé : les journaux, les contrats, les sociétés intermédiaires. Adrien est mis en cause pour le réseau de surveillance et les marchés frauduleux."),N("Mais le meurtre de Léo reste non résolu : le corps déplacé, le véhicule au feu cassé — pas assez, sans chaîne de conservation. Il tient, debout et silencieux, entre ses deux avocats."),N("Un soir, sur le téléphone d'une journaliste, un fichier anonyme :"),H("ORPHÉE — NIVEAU 2"),N("Il contient un seul nom : celui d'un enquêteur de police. Cette histoire n'est pas finie — mais ce n'est plus la tienne.")],k:"Fin · L'ombre d'Orphée"},
});
const C=a=>a.concat(Array.from({length:10-a.length},(_,i)=>["Chapitre "+(a.length+i+1),"-"]));
